(window.__ATLAS_DATA=window.__ATLAS_DATA||{})["data/acts/CF.json"]={"meta":{"id":"CF","name":"Codul familiei","short":"CF","type":"Cod","number":"1316/2000","date":"26.10.2000","published":"Publicat : 26.04.2001 în MONITORUL OFICIAL Nr. 47-48 art. 210 Data intrării în vigoare","lastAmend":"LP126 din 02.07.26, MO359-362/06.08.26 art. 361; în vigoare 06.08.26","aliases":["cod:familiei"],"titleRaw":"CODUL FAMILIEI","signature":["PREŞEDINTELE PARLAMENTULUI Eugenia OSTAPCIUC","Nr. 1316 - XIV. Chişinău, 26 octombrie 2000."],"preamble":["MODIFICAT","LP126 din 02.07.26, MO359-362/06.08.26 art. 361; în vigoare 06.08.26","Parlamentul adoptă prezentul cod."]},"nodes":[{"id":"n1","kind":"titlu","lvl":2,"label":"Titlul I","name":"DISPOZIŢII GENERALE","parent":null,"arts":[]},{"id":"n2","kind":"capitol","lvl":3,"label":"Capitolul 1","name":"LEGISLAŢIA FAMILIALĂ","parent":"n1","arts":["1","2","3","4"]},{"id":"n3","kind":"capitol","lvl":3,"label":"Capitolul 2","name":"REALIZAREA ŞI APĂRAREA DREPTURILOR FAMILIALE","parent":"n1","arts":["5","6","7","8"]},{"id":"n4","kind":"titlu","lvl":2,"label":"Titlul II","name":"CĂSĂTORIA","parent":null,"arts":[]},{"id":"n5","kind":"capitol","lvl":3,"label":"Capitolul 3","name":"CONDIŢIILE ŞI MODALITATEA DE ÎNREGISTRARE A CĂSĂTORIEI","parent":"n4","arts":["9","10","11","12","13","14","15"]},{"id":"n6","kind":"capitol","lvl":3,"label":"Capitolul 4","name":"DREPTURILE ŞI OBLIGAŢIILE PERSONALE ALE SOŢILOR","parent":"n4","arts":["16","17","18"]},{"id":"n7","kind":"capitol","lvl":3,"label":"Capitolul 5","name":"REGIMUL LEGAL AL BUNURILOR SOŢILOR","parent":"n4","arts":["19","20","21","22","23","24","25","26"]},{"id":"n8","kind":"capitol","lvl":3,"label":"Capitolul 6","name":"REGIMUL CONTRACTUAL AL BUNURILOR SOŢILOR","parent":"n4","arts":["27","28","29","30","31","32"]},{"id":"n9","kind":"capitol","lvl":3,"label":"Capitolul 7","name":"ÎNCETAREA CĂSĂTORIEI","parent":"n4","arts":["33","34","35","36","37","38","39","40"]},{"id":"n10","kind":"capitol","lvl":3,"label":"Capitolul 8","name":"DECLARAREA NULITĂŢII CĂSĂTORIEI","parent":"n4","arts":["41","42","43","43_1","44"]},{"id":"n11","kind":"titlu","lvl":2,"label":"Titlul III","name":"RELAŢIILE JURIDICE DINTRE PĂRINŢI ŞI COPII","parent":null,"arts":[]},{"id":"n12","kind":"capitol","lvl":3,"label":"Capitolul 9","name":"ATESTAREA PROVENIENŢEI COPILULUI","parent":"n11","arts":["45","46","47","48","49","50"]},{"id":"n13","kind":"capitol","lvl":3,"label":"Capitolul 10","name":"DREPTURILE COPIILOR MINORI","parent":"n11","arts":["51","52","53","54","55","56","57","57_1","57_2"]},{"id":"n14","kind":"capitol","lvl":3,"label":"Capitolul 11","name":"DREPTURILE ŞI OBLIGAŢIILE PĂRINŢILOR","parent":"n11","arts":["58","59","60","61","62","63","64","65","66","67","68","69","70","71","72","73","73_1"]},{"id":"n15","kind":"titlu","lvl":2,"label":"Titlul IV","name":"OBLIGAŢIA DE ÎNTREŢINERE DINTRE MEMBRII FAMILIEI","parent":null,"arts":[]},{"id":"n16","kind":"capitol","lvl":3,"label":"Capitolul 12","name":"OBLIGAŢIA DE ÎNTREŢINERE DINTRE PĂRINŢI ŞI COPII","parent":"n15","arts":["74","75","76","77","78","79","80","81"]},{"id":"n17","kind":"capitol","lvl":3,"label":"Capitolul 13","name":"OBLIGAŢIA DE ÎNTREŢINERE DINTRE SOŢI ŞI FOŞTII SOŢI","parent":"n15","arts":["82","83","84","85"]},{"id":"n18","kind":"capitol","lvl":3,"label":"Capitolul 14","name":"OBLIGAŢIA DE ÎNTREŢINERE DINTRE ALŢI MEMBRI AI FAMILIEI","parent":"n15","arts":["86","87","88","89","90","91"]},{"id":"n19","kind":"capitol","lvl":3,"label":"Capitolul 15","name":"CONTRACTUL PRIVIND PLATA PENSIEI DE ÎNTREŢINERE","parent":"n15","arts":["92","93","94","95","96"]},{"id":"n20","kind":"capitol","lvl":3,"label":"Capitolul 16","name":"MODUL DE ÎNCASARE ŞI DE PLATĂ A PENSIEI DE ÎNTREŢINERE","parent":"n15","arts":["97","98","99","100","101","102","103","104","105","106","107","108","109","110","111"]},{"id":"n21","kind":"titlu","lvl":2,"label":"Titlul V","name":"PROTECŢIA ŞI EDUCAŢIA COPIILOR RĂMAŞI FĂRĂ OCROTIRE PĂRINTEASCĂ","parent":null,"arts":[]},{"id":"n22","kind":"capitol","lvl":3,"label":"Capitolul 19","name":"TUTELA ŞI CURATELA COPIILOR","parent":"n21","arts":["142","143","144","145","146","147"]},{"id":"n23","kind":"titlu","lvl":2,"label":"Titlul VI","name":"REGLEMENTAREA RELAŢIILOR FAMILIALE CU ELEMENTE DE EXTRANEITATE","parent":null,"arts":["154","155","156","157","158","159","160","161","164"]},{"id":"n24","kind":"titlu","lvl":2,"label":"Titlul VII","name":"DISPOZIŢII FINALE ŞI TRANZITORII","parent":null,"arts":["165","166","167"]}],"articles":[{"id":"1","num":"1","title":"Legislaţia familială şi alte acte ce conţin norme ale dreptului familiei","node":"n2","blocks":[{"k":"al","n":"1","id":"a1","t":"Legislaţia familială constă din prezentul cod şi din alte acte normative adoptate în cazurile şi în limitele prevăzute de acesta.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Guvernul este în drept să adopte acte normative în domeniul dreptului familiei în cazurile prevăzute de prezentul cod de alte legi şi de decretele Preşedintelui Republicii Moldova.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Dacă există divergenţe între prezentul cod şi convenţiile şi tratatele ce reglementează relaţiile familiale, la care Republica Moldova este parte, au prioritate reglementările internaţionale.","lvl":1}]},{"id":"2","num":"2","title":"Principiile de bază ale legislaţiei familialе","node":"n2","blocks":[{"k":"al","n":"1","id":"a1","t":"Familia şi relaţiile familiale în Republica Moldova sînt ocrotite de stat.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Căsătoria înregistrată de autoritățile abilitate prin lege să înregistreze fapte și evenimente de stare civilă generează drepturile și obligațiile soților prevăzute de prezentul cod.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Relaţiile familiale sînt reglementate în conformitate cu următoarele principii: monogamie, căsătorie liber consimţită între bărbat şi femeie, egalitate în drepturi a soţilor în familie, sprijin reciproc moral şi material, fidelitate conjugală, prioritate a educaţiei copilului în familie, manifestare a grijii pentru întreţinerea, educaţia şi apărarea drepturilor şi intereselor membrilor minori şi ale celor inapţi de muncă ai familiei, soluţionare, pe cale amiabilă, a tuturor problemelor vieţii familiale, inadmisibilitate a amestecului deliberat în relaţiile familiale, liber acces la apărarea, pe cale judecătorească, a drepturilor şi intereselor legitime ale membrilor familiei.","lvl":1}]},{"id":"3","num":"3","title":"Relaţiile sociale reglementate de prezentul cod","node":"n2","blocks":[{"k":"p","id":"x1","t":"Prezentul cod stabileşte condiţiile şi modalitatea de înregistrare, încetare şi declarare a nulităţii căsătoriei, reglementează relaţiile personale nepatrimoniale şi patrimoniale născute din căsătorie, rudenie şi adopţie, precum şi alte relaţii sociale similare celor familiale.","lvl":1}]},{"id":"4","num":"4","title":"Aplicarea legislaţiei civile","node":"n2","blocks":[{"k":"p","id":"x1","t":"Pentru reglementarea relaţiilor personale nepatrimoniale şi patrimoniale dintre membrii familiei, prevăzute la art.3, nereglementate de legislaţia familială, se aplică legislaţia civilă în măsura în care aceasta nu contravine esenţei relaţiilor familiale.","lvl":1,"r":[[111,116,{"art":"3"}]]}]},{"id":"5","num":"5","title":"Egalitatea în relaţiile familialе","node":"n3","blocks":[{"k":"al","n":"1","id":"a1","t":"Toate persoanele căsătorite au drepturi şi obligaţii egale în relaţiile familiale, indiferent de sex, rasă, naţionalitate, origine etnică, limbă, religie, opinie, apartenenţă politică, avere şi origine socială.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Drepturile şi obligaţiile familiale sînt legate de titularii lor şi nu pot fi cedate persoanelor terţe.","lvl":1}]},{"id":"6","num":"6","title":"Realizarea drepturilor şi îndeplinirea obligaţiilor familiale","node":"n3","blocks":[{"k":"al","n":"1","id":"a1","t":"Persoanele fizice îşi realizează de sine stătător drepturile ce le aparţin şi iau naştere din relaţiile familiale, dacă prezentul cod nu prevede altfel.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Realizarea drepturilor şi îndeplinirea obligaţiilor familiale nu trebuie să lezeze drepturile, obligaţiile, libertăţile şi interesele legitime ale altor membri ai familiei şi ale altor persoane.","lvl":1}]},{"id":"7","num":"7","title":"Ocrotirea drepturilor familialе","node":"n3","blocks":[{"k":"al","n":"1","id":"a1","t":"Drepturile familiale sînt ocrotite de lege, cu excepţia cazurilor când acestea sînt realizate contrar destinaţiei sau contrar prevederilor legale.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Drepturile familiale sînt ocrotite de autorităţile abilitate ale administraţiei publice, iar în anumite cazuri de mediatori şi de instanţele judecătoreşti.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Mijloacele de ocrotire a drepturilor familiale sînt stabilite de prezentul cod, de alte legi şi acte normative.","lvl":1},{"k":"al","n":"4","id":"a4","t":"În orice conflict sau litigiu în relaţiile familiale, care creează sau ar putea crea un pericol pentru creşterea şi dezvoltarea normală a copilului sau care lezează sau afectează interesele lui legale, autoritatea tutelară recomandă membrilor familiei aflaţi în conflict sau litigiu soluţionarea acestuia în cadrul unui proces de mediere.","lvl":1}]},{"id":"8","num":"8","title":"Aplicarea prescripţiei","node":"n3","blocks":[{"k":"al","n":"1","id":"a1","t":"Cerinţele ce ţin de relaţiile familiale sînt imprescriptibile, cu excepţia cazurilor când termenele pentru apărarea dreptului lezat sînt prevăzute în mod expres de prezentul cod.","lvl":1},{"k":"al","n":"2","id":"a2","t":"La examinarea cerinţelor ce ţin de relaţiile familiale, instanţa judecătorească aplică normele care reglementează prescripţia în conformitate cu prevederile articolelor respective ale Codului civil.","lvl":1,"r":[[184,197,{"a":"cod:civil","whole":true}]]}]},{"id":"9","num":"9","title":"Înregistrarea căsătoriei","node":"n5","blocks":[{"k":"al","n":"1","id":"a1","t":"Căsătoria se înregistrează de autoritățile abilitate prin lege să înregistreze căsătoria.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Drepturile și obligațiile juridice ale soților iau naștere din ziua înregistrării căsătoriei.","lvl":1}]},{"id":"10","num":"10","title":"Cererea de înregistrare a căsătoriei","node":"n5","blocks":[{"k":"al","n":"1","id":"a1","t":"Cererea de înregistrare a căsătoriei se depune personal de către viitorii soți la autoritatea abilitată să înregistreze căsătoria.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Viitorii soți trebuie să indice în cererea de înregistrare a căsătoriei că nu există niciun impediment legal la căsătorie.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Depunerea cererii de înregistrare a căsătoriei are loc în modul stabilit de actele normative pentru înregistrarea de stat a faptelor și a evenimentelor de stare civilă.","lvl":1}]},{"id":"11","num":"11","title":"Condiţiile de înregistrare a căsătoriei","node":"n5","blocks":[{"k":"al","n":"1","id":"a1","t":"Pentru înregistrarea căsătoriei este necesar consimțământul reciproc, neviciat, exprimat personal şi necondiţionat, al bărbatului şi femeii care se căsătoresc, precum şi atingerea de către ei a vârstei matrimoniale.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Persoanele care doresc să se căsătorească sînt obligate să se informeze reciproc despre starea sănătăţii lor.","lvl":1}]},{"id":"12","num":"12","title":"Modalitatea de înregistrare a căsătoriei","node":"n5","blocks":[{"k":"p","id":"x1","t":"Locul înregistrării căsătoriei și modul de depunere a cererii de înregistrare a căsătoriei sunt stabilite de Legea nr. 100/2001 privind actele de stare civilă.","lvl":1,"r":[[109,127,{"a":"lege:100/2001","whole":true}]]}]},{"id":"13","num":"13","title":"Examenul medical al persoanelor care doresc să se căsătorească","node":"n5","blocks":[{"k":"al","n":"1","id":"a1","t":"Persoanele care doresc să se căsătorească, la solicitare, pot efectua un examen medical gratuit, în scopul depistării bolilor sau a agenţilor patogeni ce pot fi transmişi copiilor, cu acordul informat al lor.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Rezultatul examenului medical se comunică numai persoanei examinate.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Modul, termenul şi limitele examenului medical sînt stabilite de Ministerul Sănătăţii, Muncii şi Protecţiei Sociale.","lvl":1}]},{"id":"14","num":"14","title":"Vârsta matrimonială","node":"n5","blocks":[{"k":"al","n":"1","id":"a1","t":"Vârsta matrimonială minimă este de 18 ani.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Pentru motive temeinice, se poate încuviinţa înregistrarea căsătoriei cu reducerea vârstei matrimoniale, dar nu mai mult decât cu doi ani. Reducerea vârstei matrimoniale se admite cu acordul părinților minorului sau a unui părinte, în cazul în care minorul are doar un părinte, iar în lipsa părinților, cu încuviințarea autorității tutelare.","lvl":1}]},{"id":"15","num":"15","title":"Impedimente la căsătorie","node":"n5","blocks":[{"k":"al","n":"1","id":"a1","t":"Nu se admite înregistrarea căsătoriei între:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"persoane dintre care cel puţin una este deja căsătorită;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"rudele în linie dreaptă, precum și între rudele în linie colaterală, până la al IV-lea grad inclusiv;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"- abrogată;","lvl":2},{"k":"lit","n":"d","id":"a1.ld","t":"- abrogată;","lvl":2},{"k":"lit","n":"e","id":"a1.le","t":"curator şi persoană minoră aflată sub curatela acestuia, în perioada curatelei;","lvl":2},{"k":"lit","n":"f","id":"a1.lf","t":"persoane dintre care cel puţin în privința uneia este instituită o măsură de ocrotire judiciară (ocrotire provizorie, curatelă sau tutelă) şi lipsește autorizarea prevăzută de lege la înregistrarea căsătoriei;","lvl":2},{"k":"lit","n":"g","id":"a1.lg","t":"persoane condamnate la privațiune de libertate în perioada când ambele îşi ispășesc pedeapsa;","lvl":2},{"k":"lit","n":"h","id":"a1.lh","t":"persoane de acelaşi sex.","lvl":2},{"k":"al","n":"1¹","id":"a1_1","t":"În cazul adopției, dispozițiile alin. (1) lit. b) sunt aplicabile atât între persoanele care au devenit rude prin adopție, cât și între cele a căror rudenie firească a încetat prin efectul adopției.","lvl":1,"r":[[32,49,{"al":"1","lit":"b","art":"15"}]]},{"k":"al","n":"2","id":"a2","t":"Orice persoană poate face opunere la căsătorie, dacă există un impediment legal ori dacă nu sunt îndeplinite alte cerințe ale legii, prin depunerea unei cereri la autoritatea abilitată să înregistreze căsătoria, în care vor fi expuse motivele și la care vor fi anexate dovezile invocate. Autoritatea abilitată să înregistreze căsătoria este obligată să verifice opunerea la căsătorie în baza actelor de stare civilă, a dovezilor prezentate, precum și a informațiilor puse la dispoziție de către alte autorități și instituții competente. Examinarea cererii de înregistrare a căsătoriei se suspendă până la finalizarea verificării. Dacă, în urma verificării opunerii la căsătorie, impedimentele sau neîndeplinirea altor cerințe legale se confirmă, autoritatea abilitată este obligată să refuze înregistrarea căsătoriei.","lvl":1},{"k":"al","n":"3","id":"a3","t":"În cazul în care după înregistrarea unei căsătorii se atestă că aceasta a fost încheiată cu unul sau mai multe impedimente prevăzute la alin. (1) sau că aceasta contravine principiilor dreptului familiei, prestarea serviciilor de stare civilă la cererea unuia dintre soți este posibilă doar după stabilirea de către instanța judecătorească a statutului căsătoriei anterioare, după caz, după recunoașterea, în condițiile legii, a căsătoriei încheiate cu impediment.","lvl":1,"r":[[136,145,{"al":"1","art":"15"}]]}]},{"id":"16","num":"16","title":"Egalitatea soţilor în relaţiile familiale","node":"n6","blocks":[{"k":"al","n":"1","id":"a1","t":"Toate problemele vieţii familiale se soluţionează de către soţi în comun, în conformitate cu principiul egalităţii lor în relaţiile familiale.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Fiecare dintre soţi este în drept să-şi continue ori să-şi aleagă de sine stătător îndeletnicirea şi profesia.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Soţii îşi determină domiciliul în mod liber şi independent.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Relaţiile dintre soţi se bazează pe stimă şi ajutor reciproc, pe obligaţii comune de întreţinere a familiei, de îngrijire şi educaţie a copiilor.","lvl":1}]},{"id":"17","num":"17","title":"Alegerea numelui de către soți","node":"n6","blocks":[{"k":"al","n":"1","id":"a1","t":"La înregistrarea căsătoriei, fiecare dintre soți, la dorință, poate să-și păstreze numele purtat până la căsătorie ori să ia numele unuia sau altuia dintre ei, ori numele lor format prin conexare.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Conexarea numelor nu se admite atunci când cel puțin unul dintre ele este dublu. Este posibilă conexarea parțială a numelui compus.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Schimbarea numelui unuia dintre soți nu implică schimbarea numelui celuilalt soț.","lvl":1},{"k":"al","n":"4","id":"a4","t":"După desfacerea căsătoriei, soții își pot păstra numele ales la înregistrarea căsătoriei sau, după caz, pot reveni la numele purtat până la înregistrarea acesteia.","lvl":1}]},{"id":"18","num":"18","title":"Relaţiile nepatrimoniale ale soţilor","node":"n6","blocks":[{"k":"al","n":"1","id":"a1","t":"Relaţiile nepatrimoniale ale soţilor sînt reglementate de prezentul cod.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Soţii îşi datorează reciproc sprijin moral şi fidelitate conjugală.","lvl":1}]},{"id":"19","num":"19","title":"Noţiunea regimului legal al bunurilor soţilor","node":"n7","blocks":[{"k":"al","n":"1","id":"a1","t":"Bunurile dobândite de către soţi în timpul căsătoriei sînt supuse regimului proprietăţii în devălmăşie.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Regimul legal al bunurilor soţilor acţionează în măsura în care nu este modificat de contractul matrimonial.","lvl":1}]},{"id":"20","num":"20","title":"Proprietatea în devălmăşie a soţilor","node":"n7","blocks":[{"k":"al","n":"1","id":"a1","t":"Bunurile dobândite de către soţi în timpul căsătoriei aparţin ambilor cu drept de proprietate în devălmăşie, conform legislaţiei.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Sînt proprietate în devălmăşie bunurile procurate din contul:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"veniturilor obţinute de fiecare dintre soţi din:","lvl":2},{"k":"dash","id":"d1","t":"activitatea de muncă;","lvl":3},{"k":"dash","id":"d2","t":"activitatea de întreprinzător;","lvl":3},{"k":"dash","id":"d3","t":"activitatea intelectuală;","lvl":3},{"k":"lit","n":"b","id":"a2.lb","t":"premiilor, indemnizaţiilor şi altor plăţi, cu excepţia celor care au un caracter de compensare (ajutor material, despăgubire pentru vătămarea sănătăţii etc.);","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"altor mijloace comune.","lvl":2},{"k":"al","n":"3","id":"a3","t":"Sînt proprietate în devălmăşie a soţilor bunurile mobile şi imobile, valorile mobiliare, depunerile şi cotele de participaţie în capitalul social din instituţiile financiare sau societăţile comerciale, care au fost construite, constituite, procurate sau făcute din contul mijloacelor comune, precum şi alte bunuri dobândite în timpul căsătoriei, chiar dacă sînt procurate sau depuse pe numele unuia dintre soţi.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Dreptul la proprietate în devălmăşie se extinde şi asupra soţului care nu a avut un venit propriu, fiind ocupat cu gospodăria casnică, cu educaţia copiilor sau din alte motive temeinice.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Sînt proprietate în devălmăşie a soţilor bunurile care au fost dobândite din ziua înregistrării căsătoriei pînă în ziua încetării acesteia. Instanţa judecătorească este în drept, în baza cererii soţului interesat care nu este vinovat de desfacerea căsătoriei, să declare bunurile dobândite de către el în perioada cât soţii au dus gospodării separate proprietate a acestuia.","lvl":1}]},{"id":"21","num":"21","title":"Dreptul soţilor de a poseda, folosi şi dispune de bunurile comune","node":"n7","blocks":[{"k":"al","n":"1","id":"a1","t":"Soţii, de comun acord, posedă, folosesc şi dispun de bunurile comune.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Fiecare dintre soţi este în drept să încheie convenţii prin care să dispună de bunurile comune, cu excepţia bunurilor imobile, acordul celuilalt soţ fiind prezumat.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Convenţia contrară dispoziţiilor prezentului cod, prin care se micșorează ori se suprimă comunitatea de bunuri, este declarată nulă de către instanţa judecătorească.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Convenţia încheiată de unul dintre soţi poate fi declarată nulă de către instanţa judecătorească, la cererea celuilalt soţ, dacă se va stabili că cealaltă parte a convenţiei a ştiut sau trebuia să fi ştiut că al doilea soţ este împotriva încheierii convenţiei respective. Cererea privind declararea nulităţii convenţiei poate fi depusă în termen de 3 ani din momentul când celălalt soţ a aflat sau trebuia să fi aflat despre încheierea acesteia.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Unul dintre soţi nu poate, fără consimțământul expres al celuilalt, să rezilieze contractul de închiriere a spaţiului de locuit, să înstrăineze casa sau apartamentul ori să limiteze prin acte juridice dreptul la locuinţă al celuilalt soţ.","lvl":1}]},{"id":"22","num":"22","title":"Proprietatea personală a soţilor","node":"n7","blocks":[{"k":"al","n":"1","id":"a1","t":"Bunurile care au aparţinut fiecăruia dintre soţi pînă la înregistrarea căsătoriei şi bunurile primite în dar, obţinute prin moştenire sau în baza altor convenţii gratuite de către unul dintre soţi în timpul căsătoriei, sînt proprietate personală a fiecăruia dintre soţi.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Lucrurile de uz personal (îmbrăcămintea, încălţămintea şi alte obiecte), cu excepţia bijuteriilor de preţ şi altor obiecte de lux, sînt proprietate personală a soţului care le foloseşte, indiferent de timpul şi modul de dobândire.","lvl":1}]},{"id":"23","num":"23","title":"Recunoaşterea bunurilor personale ale soţilor proprietate în devălmăşie a acestora","node":"n7","blocks":[{"k":"p","id":"x1","t":"Bunurile ce aparţin fiecăruia dintre soţi pot fi recunoscute de instanţa judecătorească proprietate în devălmăşie a acestora dacă se va stabili că, în timpul căsătoriei, din contul mijloacelor comune ale soţilor sau al mijloacelor unuia dintre soţi ori în urma muncii numai a unuia dintre soţi, valoarea acestor bunuri a sporit simţitor (reparaţie capitală, reconstrucţie, reutilare, reamenajare etc.).","lvl":1}]},{"id":"24","num":"24","title":"Urmărirea bunurilor soţilor","node":"n7","blocks":[{"k":"al","n":"1","id":"a1","t":"Fiecare soţ răspunde pentru obligaţiile proprii cu bunurile proprietate personală şi cu cota-parte din proprietatea în devălmăşie, care poate fi determinată de către instanţa judecătorească la cererea creditorului.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Soţii răspund cu întreg patrimoniul lor pentru obligaţiile care au fost asumate în interesul familiei, fie şi numai de unul dintre ei, precum şi pentru repararea prejudiciului cauzat ca urmare a săvârșirii de către ei a unei infracţiuni, dacă prin aceasta au sporit bunurile comune ale soţilor.","lvl":1}]},{"id":"25","num":"25","title":"Împărţirea proprietăţii în devălmăşie a soţilor","node":"n7","blocks":[{"k":"al","n":"1","id":"a1","t":"Împărţirea proprietăţii în devălmăşie a soţilor poate fi făcută atât în timpul căsătoriei, cât şi după desfacerea ei, la cererea oricăruia dintre soţi.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Proprietatea în devălmăşie poate fi împărţită în baza acordului dintre soţi.","lvl":1},{"k":"al","n":"3","id":"a3","t":"În caz de neînţelegere, determinarea cotei-părţi a fiecărui soţ în proprietatea în devălmăşie, precum şi împărţirea acesteia în natură, se face pe cale judecătorească.","lvl":1},{"k":"al","n":"4","id":"a4","t":"La împărţirea proprietăţii în devălmăşie, instanţa judecătorească, la cererea soţilor, stabileşte bunurile ce urmează să fie transmise fiecăruia dintre ei. Dacă unuia dintre soţi îi sînt transmise bunuri care depăşesc cota ce-i revine, celuilalt soţ i se poate stabili o compensaţie bănească sau de altă natură.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Bunurile procurate pentru copiii minori (îmbrăcăminte, încălţăminte, rechizite şcolare, instrumente muzicale, jucării etc.) se transmit gratuit soţului împreună cu care locuiesc copiii.","lvl":1},{"k":"al","n":"6","id":"a6","t":"Depunerile făcute de soţi pe numele copiilor lor minori sînt proprietate a copiilor şi nu se iau în considerare la partaj.","lvl":1},{"k":"al","n":"7","id":"a7","t":"Dacă bunurile comune au fost împărţite în timpul căsătoriei, acestea devin bunuri personale ale soţilor, iar bunurile care nu au fost împărţite, precum şi bunurile dobândite ulterior de către soţi, sînt proprietate în devălmăşie a acestora.","lvl":1},{"k":"al","n":"8","id":"a8","t":"Pentru împărţirea bunurilor proprietate în devălmăşie a soţilor a căror căsătorie a fost desfăcută, se stabileşte un termen de prescripţie de 3 ani.","lvl":1}]},{"id":"26","num":"26","title":"Determinarea cotelor-părţi în proprietatea în devălmăşie a soţilor","node":"n7","blocks":[{"k":"al","n":"1","id":"a1","t":"La împărţirea proprietăţii în devălmăşie a soţilor şi determinarea cotelor-părţi din aceasta, părţile soţilor sînt considerate egale dacă contractul matrimonial nu prevede altfel.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Instanţa judecătorească este în drept să diferenţieze cotele-părţi în proprietatea în devălmăşie a soţilor, ținând cont de interesele unuia dintre soţi şi/sau de interesele copiilor minori.","lvl":1},{"k":"al","n":"3","id":"a3","t":"La împărţirea proprietăţii în devălmăşie a soţilor, datoriile comune se împart între ei proporţional cotelor-părţi ce le-au fost repartizate.","lvl":1}]},{"id":"27","num":"27","title":"Contractul matrimonial","node":"n8","blocks":[{"k":"p","id":"x1","t":"Contractul matrimonial este convenţia încheiată benevol între persoanele care doresc să se căsătorească sau între soţi, în care se determină drepturile şi obligaţiile patrimoniale ale acestora în timpul căsătoriei şi/sau în cazul desfacerii acesteia.","lvl":1}]},{"id":"28","num":"28","title":"Încheierea contractului matrimonial","node":"n8","blocks":[{"k":"al","n":"1","id":"a1","t":"Contractul matrimonial poate fi încheiat pînă la înregistrarea căsătoriei sau, în orice moment, în timpul căsătoriei.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Contractul matrimonial, încheiat pînă la înregistrarea căsătoriei intră în vigoare la data înregistrării acesteia.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Contractul matrimonial se încheie în formă scrisă şi se autentifică notarial. Nerespectarea acestor prevederi atrage nulitatea contractului.","lvl":1}]},{"id":"29","num":"29","title":"Conţinutul contractului matrimonial","node":"n8","blocks":[{"k":"al","n":"1","id":"a1","t":"Prin contractul matrimonial soţii pot modifica regimul legal al proprietăţii în devălmăşie stabilit la art.20.","lvl":1,"r":[[103,109,{"art":"20"}]]},{"k":"al","n":"2","id":"a2","t":"Contractul matrimonial poate stabili că toate bunurile dobândite de fiecare dintre soţi în timpul căsătoriei sînt proprietate personală a soţului care le-a dobândit.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Contractul matrimonial încheiat în timpul căsătoriei nu are acţiune retroactivă. Bunurile dobândite pînă la încheierea contractului sînt supuse regimului legal prevăzut de prezentul cod.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Soţii sînt în drept să determine în contractul matrimonial drepturile şi obligaţiile privind întreţinerea reciprocă şi modul de participare a fiecăruia la veniturile obţinute de fiecare dintre ei şi la cheltuielile comune, bunurile ce vor fi transmise fiecăruia dintre soţi în caz de partaj, precum şi să stabilească alte clauze patrimoniale, inclusiv sancţiuni patrimoniale pentru soţul culpabil de desfacerea căsătoriei.","lvl":1},{"k":"al","n":"4¹","id":"a4_1","t":"Soţii pot include în contractul matrimonial clauza de mediere.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Drepturile şi obligaţiile prevăzute în contractual matrimonial pot fi limitate la un anumit termen sau pot fi puse în dependenţă de survenirea sau nesurvenirea anumitelor condiţii.","lvl":1},{"k":"al","n":"6","id":"a6","t":"Părţile nu sînt în drept să stipuleze în contractul matrimonial clauze care ar afecta capacitatea juridică sau de exerciţiu a soţilor, dreptul lor de adresare în instanţa judecătorească pentru reglementarea relaţiilor personale dintre ei, inclusiv a drepturilor şi obligaţiilor dintre ei şi copiii lor, care ar limita dreptul soţului inapt de muncă la întreţinere, care ar leza drepturile şi interesele legitime ale soţilor sau ale unuia dintre ei, precum şi clauze care contravin principiilor şi naturii relaţiilor familiale.","lvl":1}]},{"id":"30","num":"30","title":"Modificarea şi rezilierea contractului matrimonial","node":"n8","blocks":[{"k":"al","n":"1","id":"a1","t":"Contractul matrimonial poate fi modificat sau, reziliat în orice moment, în baza acordului dintre soţi. Acordul privind modificarea sau rezilierea contractului matrimonial se întocmeşte în scris şi se autentifică notarial.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Nu se admite refuzul unilateral de executare a clauzelor contractului matrimonial.","lvl":1},{"k":"al","n":"3","id":"a3","t":"La cererea unuia dintre soţi, instanţa judecătorească poate modifica sau rezilia contractul matrimonial în modul şi temeiurile prevăzute de Codul civil.","lvl":1,"r":[[140,151,{"a":"cod:civil","whole":true}]]}]},{"id":"31","num":"31","title":"Încetarea şi declararea nulităţii contractului matrimonial","node":"n8","blocks":[{"k":"al","n":"1","id":"a1","t":"Clauzele contractului matrimonial se sting din momentul încetării căsătoriei, cu excepţia celor care au fost stipulate pentru perioada de după încetarea căsătoriei.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Contractul matrimonial, în baza temeiurilor prevăzute de Codul civil, poate fi declarat nul, total sau parţial, de către instanţa judecătorească.","lvl":1,"r":[[57,68,{"a":"cod:civil","whole":true}]]},{"k":"al","n":"3","id":"a3","t":"La cererea unuia dintre soţi sau autorităţii tutelare, instanţa judecătorească este în drept să declare nulitatea totală sau parţială, a contractului matrimonial dacă acesta conţine clauze care lezează drepturile şi interesele unuia dintre soţi, ale copiilor minori ori ale altor persoane ocrotite prin lege.","lvl":1}]},{"id":"32","num":"32","title":"Garanţiile drepturilor creditorilor la încheierea, modificarea şi rezilierea contractului matrimonial","node":"n8","blocks":[{"k":"al","n":"1","id":"a1","t":"Fiecare dintre soţi este obligat să înştiinţeze creditorii săi despre încheierea, modificarea sau rezilierea contractului matrimonial. În cazul neexecutării acestei obligaţii, soţul debitor răspunde pentru obligaţiile sale indiferent de conţinutul contractului.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Creditorii soţului debitor pot cere modificarea sau rezilierea contractului matrimonial dacă acesta le lezează drepturile şi interesele ocrotite prin lege.","lvl":1}]},{"id":"33","num":"33","title":"Temeiurile încetării căsătoriei","node":"n9","blocks":[{"k":"p","id":"x1","t":"Căsătoria încetează prin:","lvl":1},{"k":"lit","n":"a","id":"la","t":"desfacerea căsătoriei (divorț);","lvl":1},{"k":"lit","n":"b","id":"lb","t":"decesul unuia dintre soți;","lvl":1},{"k":"lit","n":"c","id":"lc","t":"declararea pe cale judecătorească a decesului unuia dintre soți;","lvl":1},{"k":"lit","n":"d","id":"ld","t":"declararea de către cel puțin unul dintre soți a încetării relațiilor de căsătorie în cazul în care consemnarea desfacerii căsătoriei s-a făcut în localitățile din stânga Nistrului și în municipiul Bender;","lvl":1},{"k":"lit","n":"e","id":"le","t":"constatarea judecătorească privind încetarea relațiilor de căsătorie anterioare.","lvl":1}]},{"id":"34","num":"34","title":"Limitarea dreptului soţului de a cere desfacerea căsătoriei","node":"n9","blocks":[{"k":"p","id":"x1","t":"În lipsa acordului soţiei, soţul nu poate cere desfacerea căsătoriei în timpul gravidităţii acesteia şi timp de un an după naşterea copilului dacă acesta s-a născut viu şi trăieşte.","lvl":1}]},{"id":"35","num":"35","title":"Modalitatea de desfacere a căsătoriei","node":"n9","blocks":[{"k":"p","id":"x1","t":"Căsătoria poate fi desfăcută la Agenția Servicii Publice, la misiunile diplomatice și/sau oficiile consulare ale Republicii Moldova, la notar sau pe cale judecătorească.","lvl":1}]},{"id":"36","num":"36","title":"Desfacerea căsătoriei la autoritățile abilitate","node":"n9","blocks":[{"k":"al","n":"1","id":"a1","t":"În baza acordului comun al soţilor, în cazurile în care între aceştia nu există neînţelegeri referitoare la partajul proprietăţii comune în devălmăşie, la întreţinerea, educaţia şi domiciliul copiilor minori comuni sau la întreţinerea unuia dintre soţi, căsătoria este desfăcută la autoritățile abilitate să înregistreze divorțul. Soţii participă la desfacerea căsătoriei în condiţiile Legii nr.100/2001 privind actele de stare civilă.","lvl":1,"r":[[386,403,{"a":"lege:100/2001","whole":true}]]},{"k":"al","n":"2","id":"a2","t":"La cererea unuia dintre soţi, căsătoria poate fi desfăcută la Agenția Servicii Publice dacă celălalt soţ:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"este supus unei măsuri de ocrotire judiciare;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"a fost declarat dispărut;","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"a fost condamnat la privațiune de libertate pe un termen mai mare de 3 ani, cu executarea pedepsei.","lvl":2},{"k":"al","n":"3","id":"a3","t":"Modul și condițiile de desfacere a căsătoriei sunt stabilite de Legea nr. 100/2001 privind actele de stare civilă.","lvl":1,"r":[[64,82,{"a":"lege:100/2001","whole":true}]]},{"k":"al","n":"4","id":"a4","t":"În cazul apariţiei litigiilor între soţi cu privire la copii, la partaj sau la întreţinerea unuia dintre soţi, desfacerea căsătoriei se face pe cale judecătorească.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Dacă, după desfacerea căsătoriei de către autoritățile abilitate, între soţi apar litigii referitoare la partaj, la întreţinerea, educaţia şi domiciliul copiilor minori comuni sau la întreţinerea unuia dintre soţi, acestea se vor soluţiona pe cale judecătorească.","lvl":1}]},{"id":"37","num":"37","title":"Desfacerea căsătoriei de către instanţa judecătorească","node":"n9","blocks":[{"k":"al","n":"1","id":"a1","t":"Dacă soţii au copii minori comuni şi nu au ajuns la un acord privind întreţinerea, educaţia şi domiciliul acestora sau în lipsa acordului la divorţ al unuia dintre soţi, cu excepţia cazurilor prevăzute la art.36 alin.(2) și a cazurilor în care căsătoria a fost desfăcută de notar, desfacerea căsătoriei are loc pe cale judecătorească.","lvl":1,"r":[[205,220,{"art":"36","al":"2"}]]},{"k":"al","n":"2","id":"a2","t":"Desfacerea căsătoriei are loc pe cale judecătorească şi în cazurile când există acordul la divorţ al ambilor soţi, însă unul dintre ei refuză să se prezinte la autoritatea abilitată să înregistreze divorțul pentru soluţionarea problemei.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Instanţa judecătorească va desface căsătoria dacă va constata că convieţuirea soţilor şi păstrarea familiei în continuare sînt imposibile.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Dacă, în procesul examinării cererii de desfacere a căsătoriei, unul dintre soţi nu-şi dă acordul la divorţ, instanţa judecătorească va amâna examinarea cauzei, stabilind un termen de împăcare de la o lună la 6 luni, cu excepţia cauzelor de divorţ pornite pe motivul violenţei în familie confirmate prin probe.","lvl":1},{"k":"al","n":"4¹","id":"a4_1","t":"Dacă acțiunea de desfacere a căsătoriei este pornită pe motiv de violență în familie, instanța judecătorească, la cererea victimei, solicită coordonatorului oficiului teritorial al Consiliului Național pentru Asistență Juridică Garantată de Stat desemnarea unui avocat pentru acordarea asistenței juridice garantate de stat.","lvl":1},{"k":"note","t":"[Art. 37 al. (4¹) introdus prin LP126 din 02.07.26, MO359-362/06.08.26 art. 361; în vigoare 06.08.26]","id":"n1","lvl":0},{"k":"al","n":"5","id":"a5","t":"Dacă măsurile de împăcare nu au dat efecte şi soţii continuă să insiste asupra divorţului, instanţa judecătorească va satisface cererea respectivă și se va exprima asupra numelor purtate de soți după desfacerea căsătoriei.","lvl":1}]},{"id":"38","num":"38","title":"Soluţionarea litigiilor de către instanţa judecătorească în procesul desfacerii căsătoriei","node":"n9","blocks":[{"k":"al","n":"1","id":"a1","t":"La desfacerea căsătoriei, soţii pot prezenta instanţei judecătoreşti un acord privind împărţirea bunurilor lor proprietate în devălmăşie şi plata pensiei de întreţinere a copiilor şi a unuia dintre soţi, indicând mărimea acesteia, precum şi privind determinarea părintelui împreună cu care vor locui copiii minori comuni.","lvl":1},{"k":"al","n":"2","id":"a2","t":"În cazul lipsei unui acord între soţi prevăzut la alin.(1) sau dacă se va dovedi că acordul lezează drepturile şi interesele copiilor minori sau ale unuia dintre soţi, instanţa judecătorească este obligată:","lvl":1,"r":[[50,58,{"al":"1","art":"38"}]]},{"k":"lit","n":"a","id":"a2.la","t":"să împartă, la cererea soţilor (a unuia dintre ei), bunurile lor proprietate în devălmăşie;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"să determine care dintre părinţi va plăti pensia de întreţinere a copiilor minori şi mărimea acesteia;","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"să stabilească, la cererea soţului care are dreptul la pensia de întreţinere de la celălalt soţ, mărimea şi modul de plată a acestei pensii;","lvl":2},{"k":"lit","n":"d","id":"a2.ld","t":"să stabilească cu cine dintre părinţi vor locui copiii minori după divorţ.","lvl":2},{"k":"pct","n":"3","id":"a2.ld.p3","t":"Litigiile, altele decât cele expuse în prezentul articol, nu pot fi soluţionate în procesul de desfacere a căsătoriei, cu excepţia acţiunii de contestare a paternităţii la cererea soţului.","lvl":3},{"k":"al","n":"4","id":"a4","t":"Dacă, la împărţirea bunurilor proprietate în devălmăşie a soţilor, vor fi atinse interesele persoanelor terţe, instanţa judecătorească va dispune examinarea cererii respective într-un proces aparte.","lvl":1}]},{"id":"39","num":"39","title":"Momentul încetării căsătoriei","node":"n9","blocks":[{"k":"al","n":"1","id":"a1","t":"În cazul desfacerii căsătoriei la Agenția Servicii Publice, misiunea diplomatică și/sau oficiul consular ale Republicii Moldova sau, la notar, aceasta încetează din ziua înregistrării divorţului, iar în cazul desfacerii căsătoriei pe cale judecătorească - din ziua când hotărârea instanţei judecătoreşti a rămas definitivă.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Dacă problema divorţului a fost soluţionată pe cale judecătorească, acesta urmează a fi înregistrat în modul prevăzut pentru înregistrarea de stat a actelor de stare civilă.","lvl":1},{"k":"al","n":"3","id":"a3","t":"În cazul în care hotărârea judecătorească prin care s-a pronunțat desfacerea căsătoriei a rămas definitivă, instanța judecătorească transmite hotărârea Agenției Servicii Publice prin mijloace electronice sau, în decurs de 3 zile lucrătoare, expediază o copie autentificată a acestei hotărâri subdiviziunii teritoriale a Agenției Servicii Publice din raza teritorială a instanței judecătorești.","lvl":1}]},{"id":"40","num":"40","title":"Restabilirea căsătoriei în cazul apariţiei soţului declarat decedat sau dispărut","node":"n9","blocks":[{"k":"al","n":"1","id":"a1","t":"În cazul apariţiei soţului declarat, în modul stabilit de lege, decedat sau dispărut şi anulării hotărârii respective a instanţei judecătoreşti, Agenția Servicii Publice poate restabili căsătoria respectivă, la cererea comună a soţilor, dacă celălalt soţ nu a înregistrat o nouă căsătorie.","lvl":1},{"k":"al","n":"2","id":"a2","t":"În cazul restabilirii căsătoriei, se consideră că aceasta nu a fost întreruptă. Bunurile dobândite în perioada de absenţă a unuia dintre soţi aparţin soţului care le-a dobândit.","lvl":1}]},{"id":"41","num":"41","title":"Nulitatea absolută și relativă a căsătoriei","node":"n10","blocks":[{"k":"al","n":"1","id":"a1","t":"Instanța judecătorească va declara nulitatea absolută a căsătoriei, dacă:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"aceasta a fost înregistrată cu încălcarea prevederilor art. 11 sau ale art. 15 alin. (1) lit. a), b), h) și alin. (1¹);","lvl":2,"r":[[55,62,{"art":"11"}],[71,96,{"art":"15","al":"1","lit":"a"}],[98,100,{"art":"15","al":"1","lit":"b"}],[102,104,{"art":"15","al":"1","lit":"h"}],[108,118,{"art":"15","al":"1_1"}]]},{"k":"lit","n":"b","id":"a1.lb","t":"aceasta a fost înregistrată atunci când soții sau unul dintre ei nu a avut intenția de a crea o familie (căsătorie fictivă).","lvl":2},{"k":"al","n":"2","id":"a2","t":"Căsătoria lovită de nulitate relativă poate fi anulată de instanța judecătorească în următoarele cazuri:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"aceasta a fost înregistrată cu încălcarea prevederilor art. 15 alin. (1) lit. e), f) și g);","lvl":2,"r":[[55,80,{"art":"15","al":"1","lit":"e"}],[82,84,{"art":"15","al":"1","lit":"f"}],[88,90,{"art":"15","al":"1","lit":"g"}]]},{"k":"lit","n":"b","id":"a2.lb","t":"aceasta a fost înregistrată în condițiile prevăzute de art. 14, fără acordul părinților sau fără acordul unui părinte, în cazul în care minorul are doar un părinte sau, după caz, fără încuviințarea autorității tutelare.","lvl":2,"r":[[55,62,{"art":"14"}]]},{"k":"al","n":"3","id":"a3","t":"Căsătoria declarată nulă, indiferent de temeiurile de declarare a nulității, se consideră ca atare din momentul înregistrării ei.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Instanța judecătorească transmite hotărârea privind nulitatea căsătoriei Agenției Servicii Publice prin mijloace electronice sau, în decurs de 3 zile lucrătoare, expediază o copie autentificată a acestei hotărâri subdiviziunii teritoriale a Agenției Servicii Publice din raza teritorială a instanței judecătorești.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Căsătoria se consideră nulă dacă actul de căsătorie a fost declarat nul în conformitate cu Legea nr. 100/2001 privind actele de stare civilă.","lvl":1,"r":[[91,109,{"a":"lege:100/2001","whole":true}]]}]},{"id":"42","num":"42","title":"Persoanele care au dreptul să ceară declararea nulității căsătoriei","node":"n10","blocks":[{"k":"al","n":"1","id":"a1","t":"Dreptul de a cere declararea nulității căsătoriei îl au următoarele persoane:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"soțul al cărui consimțământ a fost viciat prin eroare, prin dol sau prin violență;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"soțul minor, părinții lui, curatorii lui sau autoritatea tutelară, dacă căsătoria a fost înregistrată de o persoană care nu a atins vârsta matrimonială și această vârstă nu a fost redusă în modul stabilit. După atingerea de către soțul minor a vârstei de 18 ani, dreptul de a cere declararea nulității căsătoriei îi aparține numai lui;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"soțul ale cărui drepturi au fost încălcate prin înregistrarea căsătoriei, cu încălcarea obligației prevăzute la art. 11 alin. (2);","lvl":2,"r":[[112,129,{"art":"11","al":"2"}]]},{"k":"lit","n":"d","id":"a1.ld","t":"soțul, precum și alte persoane, ale căror drepturi și interese au fost lezate în urma înregistrării căsătoriei cu încălcarea prevederilor art. 15 alin. (1) lit. a);","lvl":2,"r":[[138,163,{"art":"15","al":"1","lit":"a"}]]},{"k":"lit","n":"e","id":"a1.le","t":"orice persoană interesată, în cazul căsătoriei înregistrate cu încălcarea prevederilor art. 15 alin. (1) lit. b), e), f), g), h) și alin. (1¹);","lvl":2,"r":[[87,112,{"art":"15","al":"1","lit":"b"}],[114,116,{"art":"15","al":"1","lit":"e"}],[118,120,{"art":"15","al":"1","lit":"f"}],[122,124,{"art":"15","al":"1","lit":"g"}],[126,128,{"art":"15","al":"1","lit":"h"}],[132,142,{"art":"15","al":"1_1"}]]},{"k":"lit","n":"f","id":"a1.lf","t":"subiecții a căror autorizare este necesară la înregistrarea căsătoriei cu o persoană în privința căreia este instituită o măsură de ocrotire judiciară;","lvl":2},{"k":"lit","n":"g","id":"a1.lg","t":"soțul de bună-credință, în cazul în care a fost înregistrată o căsătorie fictivă, precum și autoritatea competentă pentru străini, în cazul în care declararea caracterului fictiv al căsătoriei prezintă relevanță pentru exercitarea atribuțiilor legale ale acesteia.","lvl":2},{"k":"al","n":"2","id":"a2","t":"Cererea privind declararea nulității căsătoriei înregistrate cu un minor care nu a atins vârsta matrimonială se examinează cu participarea obligatorie a reprezentantului autorității tutelare.","lvl":1}]},{"id":"43","num":"43","title":"Împrejurările care înlătură nulitatea Căsătoriei","node":"n10","blocks":[{"k":"al","n":"1","id":"a1","t":"Căsătoria înregistrată cu o persoană a cărei căsătorie anterioară nu a fost încetată se recunoaște valabilă dacă, în momentul atestării impedimentului respectiv în cadrul unei proceduri administrative, acest impediment a dispărut. Căsătoria se consideră valabilă din momentul dispariției impedimentului respectiv.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Instanța judecătorească poate recunoaște valabilă o căsătorie dacă, în momentul examinării cauzei de nulitate sau de recunoaștere a valabilității acestei căsătorii, impedimentele care împiedicau înregistrarea acesteia au dispărut. Căsătoria este recunoscută valabilă din momentul dispariției impedimentului.","lvl":1},{"k":"al","n":"3","id":"a3","t":"În cazul constatării că unul dintre soți are una sau mai multe căsătorii anterioare neîncetate, valabilitatea căsătoriei poate fi recunoscută doar după ce instanța judecătorească se pronunță cu privire la încetarea căsătoriei sau, după caz, a căsătoriilor anterioare. Căsătoria anterioară încetează la data recunoașterii drept valabilă a căsătoriei următoare.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Instanța judecătorească are dreptul să respingă cererea de declarare a nulității căsătoriei înregistrate de un minor care nu a atins vârsta matrimonială, dacă aceasta o cer interesele minorului.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Nu poate fi declarată nulă o căsătorie înregistrată cu încălcarea prevederilor legate de vârstă matrimonială în situația în care, în timpul examinării cauzei, ambii soți au împlinit vârsta de 18 ani sau dacă soția a născut ori a rămas gravidă.","lvl":1},{"k":"al","n":"6","id":"a6","t":"Căsătoria fictivă nu poate fi declarată nulă dacă, în timpul examinării cauzei, a intervenit conviețuirea soților sau dacă soția a născut ori a rămas gravidă.","lvl":1},{"k":"al","n":"7","id":"a7","t":"O căsătorie nu poate fi declarată nulă după încetarea ei, cu excepția cazului în care, la momentul înregistrării acesteia, unul dintre soți se afla într-o altă căsătorie.","lvl":1}]},{"id":"43_1","num":"43¹","title":"Termenul de prescripție pentru invocarea unor temeiuri particulare de nulitate","node":"n10","blocks":[{"k":"p","id":"x1","t":"Anularea căsătoriei poate fi solicitată în termen de doi ani, în cazul:","lvl":1},{"k":"lit","n":"a","id":"la","t":"prevăzut la art. 15 alin. (1) lit. e), de la data înregistrării căsătoriei;","lvl":1,"r":[[12,37,{"art":"15","al":"1","lit":"e"}]]},{"k":"lit","n":"b","id":"lb","t":"prevăzut la art. 15 alin. (1) lit. f), de la data la care autoritatea competentă a cărei autorizare era necesară pentru înregistrarea căsătoriei a luat cunoștință de aceasta;","lvl":1,"r":[[12,37,{"art":"15","al":"1","lit":"f"}]]},{"k":"lit","n":"c","id":"lc","t":"nulității căsătoriei pentru vicii de consimțământ sau pentru lipsă de discernământ, de la data încetării violenței sau, după caz, de la data la care cel interesat a cunoscut dolul, eroarea ori lipsa temporară a discernământului.","lvl":1}]},{"id":"44","num":"44","title":"Consecințele de declarare a nulităţii căsătoriei","node":"n10","blocks":[{"k":"al","n":"1","id":"a1","t":"Căsătoria declarată nulă de către instanţa judecătorească se consideră ca atare din ziua înregistrării ei şi nu dă naştere la drepturi şi obligaţii între soţi, cu excepţiile prevăzute de prezentul articol.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Bunurile procurate în comun de către persoanele a căror căsătorie a fost declarată nulă aparţin acestora cu drept de proprietate în devălmășie, iar contractul matrimonial se consideră nul.","lvl":1},{"k":"al","n":"3","id":"a3","t":"În cazul în care căsătoria este declarată nulă:","lvl":1},{"k":"lit","n":"a","id":"a3.la","t":"instanţa judecătorească, la cererea soţului de bună-credinţă, este în drept să-l oblige pe celălalt soţ la plata pensiei de întreţinere, să aplice, la împărţirea bunurilor dobândite în comun pînă la declararea nulităţii căsătoriei, regulile stabilite de art.20, 25, 26, precum şi să recunoască valabil, total sau parţial, contractul matrimonial;","lvl":2,"r":[[254,260,{"art":"20"}],[262,264,{"art":"25"}],[266,268,{"art":"26"}]]},{"k":"lit","n":"b","id":"a3.lb","t":"soţul de bună-credinţă este în drept să ceară, în modul stabilit de legislaţia civilă, repararea prejudiciului moral şi material cauzat.","lvl":2},{"k":"al","n":"4","id":"a4","t":"Nulitatea căsătoriei nu are niciun efect asupra copiilor născuți din această căsătorie. Drepturile și obligațiile părinților a căror căsătorie a fost declarată nulă și copiii acestora cad sub incidența dispozițiilor cu privire la divorț.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Declararea nulităţii căsătoriei nu afectează drepturile copiilor născuţi din această căsătorie.","lvl":1}]},{"id":"45","num":"45","title":"Rudenia şi afinitatea","node":"n12","blocks":[{"k":"al","n":"1","id":"a1","t":"Rudenia este legătura bazată pe descendenţa unei persoane dintr-o altă persoană sau pe faptul că mai multe persoane au un ascendent comun. În primul caz, rudenia este în linie dreaptă, iar în al doilea caz - în linie colaterală.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Gradul de rudenie se stabileşte prin numărul de naşteri.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Rudele unuia dintre soţi sînt afinii celuilalt soţ. Linia şi gradul de afinitate sînt similare liniei şi gradului de rudenie.","lvl":1}]},{"id":"46","num":"46","title":"Temeiurile apariţiei drepturilor şi obligaţiilor reciproce ale părinţilor şi copiilor","node":"n12","blocks":[{"k":"p","id":"x1","t":"Drepturile şi obligaţiile reciproce ale părinţilor şi copiilor rezultă din provenienţa copiilor, atestată în modul stabilit de lege.","lvl":1}]},{"id":"47","num":"47","title":"Stabilirea provenienţei copilului","node":"n12","blocks":[{"k":"al","n":"1","id":"a1","t":"Proveniența copilului de la mamă (maternitatea) se stabilește în baza datelor din înregistrarea constatării medicale a nașterii copilului de la o anumită femeie într-o instituție medico-sanitară.","lvl":1},{"k":"al","n":"2","id":"a2","t":"În cazul în care nașterea a avut loc în afara unei instituții medico-sanitare, înregistrarea constatării medicale a nașterii se efectuează de instituția medico-sanitară teritorială, abilitată cu dreptul de eliberare a certificatului medical constatator al nașterii în baza concluziei unui consiliu, instituit în acest scop de conducătorul instituției medico-sanitare, în termen de 3 zile lucrătoare, după cum urmează:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"în cazul constatării nașterii în cadrul termenului de 10 zile de la data nașterii, înregistrarea constatării medicale a nașterii se efectuează numai după o examinare medicală a lăuzei și a nou-născutului de către un consiliu format din doi medici obstetricieni-ginecologi și un medic neonatolog (medic pediatru);","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"în cazul constatării nașterii după expirarea termenului de 10 zile, dar până la 42 de zile de la data nașterii, din consiliu va face parte, suplimentar, și reprezentantul autorității tutelare în a cărei rază teritorială este constatată nașterea;","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"în cazul constatării nașterii după expirarea termenului de 42 de zile de la data nașterii, înregistrarea constatării medicale a nașterii de către instituția medico-sanitară se efectuează în baza testelor de confirmare a maternității;","lvl":2},{"k":"lit","n":"d","id":"a2.ld","t":"în cazul în care consiliul, ca urmare a examinării medicale și a materialelor prezentate și examinate, nu poate stabili producerea nașterii în afara instituției medico-sanitare, conducătorul instituției medico-sanitare emite o decizie de refuz și recomandă părinților să se adreseze în instanța de judecată.","lvl":2},{"k":"al","n":"3","id":"a3","t":"Copilul născut din părinţi căsătoriţi ori în timp de 300 de zile din momentul desfacerii căsătoriei, declarării căsătoriei nule sau decesului soţului mamei copilului are ca tată pe soţul (fostul soţ) al mamei, dacă nu a fost stabilit contrariul.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Prezumţia de paternitate a soţului (fostului soţ) poate fi înlăturată printr-o declaraţie a soţilor (foştilor soţi) depusă personal. În cazul în care soţii (unul din ei) nu se pot prezenta personal, declaraţia se autentifică notarial şi se expediază la autoritatea abilitată să înregistreze nașterea.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Paternitatea copilului născut în afara căsătoriei poate fi recunoscută de către tatăl său printr-o declaraţie comună a acestuia şi a mamei copilului, depusă la autoritatea abilitată să înregistreze nașterea.","lvl":1},{"k":"al","n":"5¹","id":"a5_1","t":"Recunoașterea paternității de către părintele care are 16 ani împliniți, dacă acesta nu este căsătorit, se efectuează cu acordul reprezentantului legal al acestuia, iar în lipsa reprezentantului legal, cu acordul autorității tutelare.","lvl":1},{"k":"al","n":"6","id":"a6","t":"În cazurile când mama este decedată, declarată decedată sau dispărută ori când nu i se cunoaşte locul aflării, precum şi în cazul decăderii ei din drepturile părinteşti, paternitatea se stabileşte în baza declaraţiei tatălui şi a acordului scris al autorităţii tutelare sau prin hotărârea instanţei judecătoreşti dacă lipseşte un astfel de acord. În cazul în care în privința mamei este instituită o măsură de ocrotire judiciară, se aplică prevederile art. 116 și 117 din Codul civil nr. 1107/2002.","lvl":1,"r":[[452,460,{"art":"116","a":"cod:civil"}],[464,467,{"art":"117","a":"cod:civil"}],[472,497,{"a":"cod:civil","whole":true}]]},{"k":"al","n":"7","id":"a7","t":"Declaraţia comună a mamei şi tatălui copilului privind paternitatea poate fi depusă la autoritatea abilitată şi pînă la naşterea copilului.","lvl":1}]},{"id":"48","num":"48","title":"Stabilirea paternităţii în instanţa judecătorească","node":"n12","blocks":[{"k":"p","id":"x1","t":"Dacă copilul este născut din părinţi necăsătoriţi între ei şi în lipsa declaraţiei comune a părinţilor sau a tatălui copilului, paternitatea se stabileşte de către instanţa judecătorească în baza declaraţiei unuia dintre părinţi, a tutorelui (curatorului) copilului sau a copilului însuşi la atingerea majoratului.","lvl":1}]},{"id":"49","num":"49","title":"Contestarea paternităţii (maternităţii)","node":"n12","blocks":[{"k":"al","n":"1","id":"a1","t":"Paternitatea (maternitatea) poate fi contestată numai pe cale judecătorească de către persoanele înscrise drept tată sau mamă sau de către persoanele care sînt mama sau tatăl firesc al copilului, de către copil la atingerea majoratului, de către tutorele (curatorul) copilului. În cazul în care în privința părintelui este instituită o măsură de ocrotire judiciară, se aplică prevederile art. 116 și 117 din Codul civil nr. 1107/2002.","lvl":1,"r":[[388,396,{"art":"116","a":"cod:civil"}],[400,403,{"art":"117","a":"cod:civil"}],[408,433,{"a":"cod:civil","whole":true}]]},{"k":"al","n":"2","id":"a2","t":"- abrogat.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Nu au dreptul să conteste paternitatea:","lvl":1},{"k":"lit","n":"a","id":"a3.la","t":"soţul care şi-a dat acordul scris la fecundarea artificială sau implantarea embrionului soţiei;","lvl":2},{"k":"lit","n":"b","id":"a3.lb","t":"persoana care a fost înscrisă drept tată al copilului în baza declaraţiei comune a acesteia şi a mamei copilului sau în baza declaraţiei proprii, dacă în momentul depunerii acesteia ştia că nu este tatăl firesc al copilului.","lvl":2}]},{"id":"50","num":"50","title":"Drepturile şi obligaţiile copiilor născuţi în afara căsătoriei","node":"n12","blocks":[{"k":"p","id":"x1","t":"Copiii născuţi în afara căsătoriei au aceleaşi drepturi şi obligaţii faţă de părinţii şi rudele lor ca şi cei născuţi de la persoane căsătorite.","lvl":1}]},{"id":"51","num":"51","title":"Dreptul copilului la abitaţie şi educaţie în familie","node":"n13","blocks":[{"k":"al","n":"1","id":"a1","t":"Se consideră copil persoana care nu a atins vârsta de 18 ani (majoratul).","lvl":1},{"k":"al","n":"2","id":"a2","t":"Fiecare copil are dreptul să locuiască în familie, să-şi cunoască părinţii, să beneficieze de grija lor, să coabiteze cu ei, cu excepţia cazurilor când aceasta contravine intereselor copilului.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Copilul are dreptul la educaţie din partea părinţilor, la dezvoltarea capacităţilor intelectuale, la libertatea gândirii şi conştiinţei, la apărarea demnităţii şi onoarei.","lvl":1},{"k":"al","n":"4","id":"a4","t":"În cazul copiilor separaţi de părinţi, drepturile copilului la îngrijire şi educație sînt asigurate de reprezentantul legal.","lvl":1}]},{"id":"52","num":"52","title":"Dreptul copilului de a comunica cu părinţii şi alte rude","node":"n13","blocks":[{"k":"al","n":"1","id":"a1","t":"Copilul are dreptul să comunice cu ambii părinţi, cu buneii, fraţii, surorile şi cu celelalte rude. Desfacerea căsătoriei părinţilor, nulitatea ei sau traiul separat al acestora nu afectează drepturile copilului. În cazul când părinţii au domiciliul separat, copilul are dreptul să comunice cu fiecare dintre ei.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Copilul aflat în situaţii extreme (reţinere, arest etc.) are dreptul să ia legătura cu părinţii sau cu alte rude în modul stabilit. Dacă nu este posibil de a contacta părinţii sau rudele copilului, va fi anunţată imediat autoritatea tutelară.","lvl":1},{"k":"al","n":"3","id":"a3","t":"În cazul copiilor cărora li s-a stabilit statut de copil rămas temporar fără ocrotire părintească, conform prevederilor art. 14 alin. (1) lit. c) și f) din Legea nr. 140/2013 privind protecția specială a copiilor aflați în situație de risc și a copiilor separați de părinți, la solicitarea copilului sau a părintelui/părinților (cu acordul copilului), autoritatea tutelară teritorială asigură vizitarea trimestrială a părintelui/părinților de către copil, dacă în privința părintelui/părinților nu se află în derulare procese judiciare privind decăderea din drepturile părintești.","lvl":1,"r":[[120,145,{"art":"14","al":"1","lit":"c","a":"lege:140/2013"}],[149,151,{"art":"14","al":"1","lit":"f","a":"lege:140/2013"}],[156,174,{"a":"lege:140/2013","whole":true}]]}]},{"id":"53","num":"53","title":"Dreptul copilului de a fi protejat","node":"n13","blocks":[{"k":"al","n":"1","id":"a1","t":"Copilului i se garantează apărarea drepturilor şi intereselor sale legitime.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Apărarea drepturilor şi intereselor legitime ale copilului se asigură de părinţi sau persoanele care îi înlocuiesc, iar în cazurile prevăzute de lege de autoritatea tutelară teritorială sau de alte organe abilitate. Părinţii poartă răspundere, prevăzută de legislaţie, pentru neîndeplinirea sau îndeplinirea necorespunzătoare a obligaţiilor de îngrijire şi educaţie a copilului.","lvl":1},{"k":"al","n":"2¹","id":"a2_1","t":"Apărarea drepturilor și intereselor legitime ale copilului ai cărui părinte/părinți sunt minori, se asigură de către părinții sau alți reprezentanți legali ai părinților minori.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Minorul care a căpătat capacitatea deplină de exerciţiu pînă la atingerea majoratului îşi apără drepturile şi interesele legitime de sine stătător.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Copilul are dreptul la protecţie contra abuzurilor, inclusiv contra pedepsei corporale din partea părinţilor sau a persoanelor care îi înlocuiesc.","lvl":1},{"k":"al","n":"5","id":"a5","t":"În cazul încălcării drepturilor şi intereselor legitime ale copilului, inclusiv prin neîndeplinirea sau îndeplinirea necorespunzătoare de către părinţi (a unuia dintre ei) a obligaţiilor de întreţinere, educaţie şi instruire, sau în cazul abuzului de drepturile părinteşti, copilul poate să se adreseze de sine stătător autorităţii tutelare teritoriale pentru apărarea drepturilor şi intereselor sale legitime, iar de la vârsta de 14 ani – instanţei judecătoreşti.","lvl":1},{"k":"al","n":"5¹","id":"a5_1","t":"Dacă plasarea copilului într-un serviciu social de plasament a fost determinată de violenţă, neglijare, exploatare, abandon sau de alte acțiuni care pun în pericol viața și sănătatea copilului, instanţa de judecată, la cererea autorităţii tutelare teritoriale, va examina posibilitatea de încasare de la părintele/părinţii culpabili a cheltuielilor pentru îngrijirea şi educaţia copilului în serviciul/serviciile sociale de plasament din momentul plasării pînă în momentul reintegrării copilului în familia părinţilor, în condițiile stabilite de Guvern.","lvl":1},{"k":"al","n":"6","id":"a6","t":"Angajaţii autorităţilor administrației publice centrale şi locale, ai structurilor, instituţiilor şi serviciilor din cadrul sau din subordinea acestora, care activează în domeniile asistenţei sociale, educaţiei, ocrotirii sănătăţii, în organele de drept, în conformitate cu mecanismul intersectorial de cooperare pentru identificarea, evaluarea, referirea, asistenţa şi monitorizarea copiilor victime şi potenţiale victime ale violenţei, neglijării, exploatării şi traficului, sînt obligaţi să transmită autorităţii tutelare teritoriale sesizările privind copiii aflaţi în situaţie de risc, precum şi cele privind cazurile de violenţă, neglijare sau exploatare a copiilor în cadrul serviciilor sociale, al instituţiilor medicale, educaţionale și culturale.","lvl":1},{"k":"al","n":"7","id":"a7","t":"Persoanele fizice care deţin informaţii despre un caz suspect de violenţă, neglijare sau exploatare a copilului sînt obligate să le comunice autorităţii tutelare teritoriale sau organelor de drept.","lvl":1}]},{"id":"54","num":"54","title":"Dreptul copilului la exprimarea opiniei","node":"n13","blocks":[{"k":"p","id":"x1","t":"Copilul are dreptul să-şi exprime opinia la soluţionarea în familie a problemelor care îi ating interesele şi să fie audiat în cursul dezbaterilor judiciare sau administrative, precum și în cadrul procedurilor notariale. De opinia copilului se ţine cont în mod obligatoriu, în conformitate cu vârsta și gradul său de maturitate, dacă aceasta nu contravine intereselor copilului.","lvl":1}]},{"id":"55","num":"55","title":"Dreptul copilului la nume şi prenume","node":"n13","blocks":[{"k":"al","n":"1","id":"a1","t":"Copilul are dreptul la un nume şi prenume.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Copilul dobândește numele părinților săi. Dacă părinții poartă nume diferite, copilul poate lua numele tatălui sau al mamei, sau un nume format prin atribuirea ori conexarea numelor părinților. Dacă un părinte poartă un nume compus, este posibilă conexarea parțială a numelui părintelui. La atribuirea numelui prin conexare, numele copilului va fi compus din două nume.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Copilul va purta un prenume simplu sau unul compus, potrivit voinţei ambilor părinţi.","lvl":1},{"k":"al","n":"4","id":"a4","t":"În caz de litigiu între părinţi privind numele şi/sau prenumele copilului, decide autoritatea tutelară.","lvl":1}]},{"id":"56","num":"56","title":"Schimbarea numelui și/sau a prenumelui copilului","node":"n13","blocks":[{"k":"al","n":"1","id":"a1","t":"Numele și/sau prenumele copilului poate fi schimbat în baza cererii comune a părinților.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Cererea de schimbare a numelui și/sau a prenumelui copilului poate fi depusă de către un părinte, dacă celălalt părinte:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"este declarat dispărut fără veste, decedat sau declarat decedat;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"este supus unei măsuri de ocrotire judiciară;","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"este decăzut din drepturile părintești;","lvl":2},{"k":"lit","n":"d","id":"a2.ld","t":"nu a stabilit filiația sa asupra copilului, în condițiile legii.","lvl":2},{"k":"al","n":"3","id":"a3","t":"În caz de litigiu între părinți, problema privind schimbarea numelui și/sau a prenumelui copilului este soluționată de către autoritatea tutelară în a cărei rază teritorială își are domiciliul copilul, ținând cont în exclusivitate de interesele copilului.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Decizia autorității tutelare poate fi contestată în instanța judecătorească. În procesul examinării cauzei de contestare sau de anulare a deciziei autorității tutelare, instanța judecătorească decide asupra numelui pe care îl va purta copilul, ținând cont în exclusivitate de interesele acestuia.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Schimbarea numelui și/sau a prenumelui copilului care a atins vârsta de 10 ani se face, în toate cazurile, cu acordul acestuia.","lvl":1}]},{"id":"57","num":"57","title":"Drepturile patrimoniale ale copilului","node":"n13","blocks":[{"k":"al","n":"1","id":"a1","t":"Copilul este proprietar al veniturilor obţinute, al bunurilor primite în dar, moştenite sau dobândite într-un alt mod, şi al tuturor bunurilor procurate din mijloacele lui.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Dreptul de proprietate al copilului este realizat în modul stabilit de Codul civil.","lvl":1,"r":[[71,82,{"a":"cod:civil","whole":true}]]},{"k":"al","n":"3","id":"a3","t":"Copilul nu are drept de proprietate asupra bunurilor părinţilor, iar părinţii - asupra bunurilor copiilor, excepţie făcând dreptul la moştenire şi dreptul la întreţinere. Părinţii şi copiii care locuiesc împreună posedă şi folosesc bunurile fiecăruia dintre ei de comun acord.","lvl":1},{"k":"al","n":"4","id":"a4","t":"În cazul apariţiei bunurilor comune ale părinţilor şi copiilor, drepturile de posesie, de folosinţă şi de dispoziţie a acestora sînt reglementate de legislaţia civilă.","lvl":1}]},{"id":"57_1","num":"57¹","title":"Dreptul copilului la repararea prejudiciului material şi moral","node":"n13","blocks":[{"k":"al","n":"1","id":"a1","t":"Copilul are dreptul la repararea prejudiciului material şi moral cauzat prin vătămarea integrităţii corporale sau a sănătăţii, prin încălcarea drepturilor personale nepatrimoniale ca urmare a violenţei, neglijării, exploatării sau eschivării în orice alt mod a părinţilor de a-şi exercita drepturile şi obligaţiile părinteşti, care au prejudiciat viața și sănătatea copilului, precum şi prin neîndeplinirea sau îndeplinirea necorespunzătoare de către o autoritate publică sau instituţie a obligaţiei stabilite de actele normative în scopul protecţiei contra riscului de producere a unui anumit prejudiciu.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Repararea prejudiciului material şi moral are loc în modul prevăzut de legislaţia civilă.","lvl":1}]},{"id":"57_2","num":"57²","title":"Autorităţile tutelare în domeniul protecţiei copilului","node":"n13","blocks":[{"k":"p","id":"x1","t":"Autorităţile tutelare sînt:","lvl":1},{"k":"lit","n":"a","id":"la","t":"autoritatea tutelară teritorială – structurile teritoriale de asistență socială din subordinea agenției teritoriale de asistență socială, Direcția generală pentru protecția drepturilor copilului din Chișinău și Direcția principală a sănătății și protecției sociale a unității teritoriale autonome Găgăuzia. În municipiile Bălţi şi Chişinău, autorităţile tutelare teritoriale exercită şi atribuţiile de autoritate tutelară, cu excepţia unităţilor administrativ-teritoriale autonome din componenţa acestora, în cadrul cărora atribuţiile de autoritate tutelară sînt exercitate de primarii unităţilor administrativ-teritoriale respective;","lvl":1},{"k":"lit","n":"b","id":"lb","t":"autoritatea tutelară – primarii de sate (comune), orașe și municipii (cu excepția municipiilor Bălți și Chișinău).","lvl":1}]},{"id":"58","num":"58","title":"Drepturile şi obligaţiile părinţilor","node":"n14","blocks":[{"k":"al","n":"1","id":"a1","t":"Părinţii au drepturi şi obligaţii egale faţă de copii, indiferent de faptul dacă copiii sînt născuţi în căsătorie sau în afara ei, dacă locuiesc împreună cu părinţii sau separat, cu excepția cazurilor în care instanța judecătorească a limitat, pentru o anumită perioadă, dreptul părintelui de a comunica cu copilul pe motiv de violență în familie.","lvl":1},{"k":"note","t":"[Art. 58 al. (1) modificat prin LP126 din 02.07.26, MO359-362/06.08.26 art. 361; în vigoare 06.08.26]","id":"n1","lvl":0},{"k":"al","n":"1¹","id":"a1_1","t":"Părinții/reprezentantul legal al părintelui minor exercită drepturile și obligațiile părintești și asupra copilului părintelui minor, precum și sunt reprezentanți legali ai copilului respectiv.","lvl":1},{"k":"al","n":"1²","id":"a1_2","t":"Părintele minor își păstrează dreptul de a participa la creșterea, îngrijirea și educația copilului.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Drepturile şi obligaţiile părinţilor, cu excepţiile prevăzute de prezentul cod, încetează din momentul atingerii majoratului sau obţinerii capacităţii depline de exerciţiu de către copil.","lvl":1}]},{"id":"59","num":"59","title":"Drepturile părinţilor minori","node":"n14","blocks":[{"k":"al","n":"1","id":"a1","t":"Părinţii minori au dreptul să locuiască împreună cu copilul lor şi să participe la educaţia lui.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Părinţii minori necăsătoriţi pot recunoaşte şi contesta paternitatea şi maternitatea în baze generale. Părinţii minori care nu au atins vârsta de 16 ani pot cere stabilirea paternităţii pe cale judecătorească.","lvl":1}]},{"id":"60","num":"60","title":"Drepturile şi obligaţiile părinţilor privind educaţia şi instruirea copiilor","node":"n14","blocks":[{"k":"al","n":"1","id":"a1","t":"Părinţii au dreptul şi sînt obligaţi să-şi educe copiii conform propriilor convingeri, indiferent de faptul dacă locuiesc împreună sau separat, cu excepția cazurilor în care instanța judecătorească a limitat, pentru o anumită perioadă, dreptul părintelui de a comunica cu copilul pe motiv de violență în familie.","lvl":1},{"k":"note","t":"[Art. 60 al. (1) modificat prin LP126 din 02.07.26, MO359-362/06.08.26 art. 361; în vigoare 06.08.26]","id":"n1","lvl":0},{"k":"al","n":"2","id":"a2","t":"Părinţii poartă răspundere pentru dezvoltarea fizică, intelectuală şi spirituală a copiilor şi au prioritate la educaţia lor faţă de oricare alte persoane.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Părinţii sînt obligaţi să asigure frecventarea de către copil a şcolii pînă la sfârșitul anului de învățământ în care acesta atinge vârsta de 16 ani. Instituţia de învățământ şi forma de instruire sînt alese de către părinţi, cu luarea în considerare a opiniei copilului.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Litigiile dintre părinţi privind educaţia şi instruirea copiilor se soluţionează de către autoritatea tutelară, iar decizia acesteia poate fi atacată pe cale judecătorească. Autoritatea tutelară recomandă părinţilor să se adreseze unui mediator pentru soluţionarea litigiului.","lvl":1}]},{"id":"61","num":"61","title":"Apărarea drepturilor şi intereselor legitime ale copiilor","node":"n14","blocks":[{"k":"al","n":"1","id":"a1","t":"Drepturile şi interesele legitime ale copiilor sînt apărate de către părinţii lor.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Părinţii sînt reprezentanţii legali ai copiilor lor şi acţionează în numele lor în relaţiile cu toate persoanele fizice şi juridice, inclusiv în autorităţile administraţiei publice şi instanţele judecătoreşti, fără a avea nevoie de împuterniciri speciale.","lvl":1},{"k":"al","n":"2¹","id":"a2_1","t":"Părinții sunt în drept să-și delege parțial drepturile și obligațiile privind creșterea, îngrijirea și educația copilului unui custode, prin depunerea unei cereri la autoritatea tutelară, conform procedurii stabilite de legislație. În acest caz, părinții rămân a fi reprezentanții legali ai copilului, iar custodele exercită atribuții de responsabil legal al copilului, în condițiile legislației.","lvl":1},{"k":"al","n":"3","id":"a3","t":"În cazul existenţei unor conflicte de interese între părinţi şi copii, acestea se soluţionează prin decizia autorității tutelare de la locul aflării copilului, care poate fi atacată pe cale judecătorească, interesele copiilor, în acest caz, fiind reprezentate de către autoritatea tutelară teritorială.","lvl":1}]},{"id":"62","num":"62","title":"Exercitarea drepturilor părinţilor","node":"n14","blocks":[{"k":"al","n":"1","id":"a1","t":"Drepturile părinţilor nu pot fi exercitate contrar intereselor copilului lor. Părinţii nu pot prejudicia sănătatea fizică şi psihică a copilului.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Metodele de educaţie a copilului, alese de părinţi, vor exclude comportamentul abuziv, insultele şi maltratările de orice fel, discriminarea, violenţa psihică şi fizică, aplicarea pedepselor corporale, antrenarea în acţiuni criminale, iniţierea în consumul de băuturi alcoolice, folosirea substanţelor stupefiante şi psihotrope, practicarea jocurilor de noroc, cerşitul şi alte acte ilicite.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Toate problemele privind educaţia şi instruirea copilului se soluţionează de către părinţi de comun acord, ţinându-se cont de interesele şi de părerea copilului.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Părinţii poartă răspundere, în modul stabilit, pentru exercitarea drepturilor părinteşti în detrimentul intereselor copilului.","lvl":1}]},{"id":"63","num":"63","title":"Domiciliul copilului minor","node":"n14","blocks":[{"k":"al","n":"1","id":"a1","t":"În cazul când părinţii locuiesc separat, domiciliul copilului care nu a atins vârsta de 14 ani se determină prin acordul părinţilor.","lvl":1},{"k":"al","n":"1¹","id":"a1_1","t":"În cazul în care părinții locuiesc separat, copilul care a atins vârsta de 14 ani alege cu care dintre părinți vrea să locuiască. Dacă acesta refuză să aleagă cu care părinte vrea să locuiască, domiciliul copilului se stabilește prin acordul părinților.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Dacă lipsește acordul părinților cu privire la stabilirea domiciliului copilului, iar copilul care a împlinit vârsta de 14 ani refuză să aleagă cu care părinte vrea să locuiască, domiciliul minorului se stabilește de către instanța de judecată, ținând cont de interesele și opinia copilului, în conformitate cu vârsta și gradul său de maturitate. În acest caz, instanţa judecătorească va lua în considerare atașamentul copilului faţă de fiecare dintre părinţi, faţă de frați şi surori, vârsta copilului, calitățile morale ale părinţilor, relaţiile existente între fiecare părinte şi copil, posibilitățile părinţilor de a crea condiţii adecvate pentru educaţia şi dezvoltarea copilului (îndeletnicirile şi regimul de lucru, condiţiile de trai etc.)","lvl":1},{"k":"al","n":"3","id":"a3","t":"La determinarea domiciliului copilului minor, instanţa judecătoreasă va cere şi avizul autorităţii tutelare teritoriale în a cărei rază teritorială se află domiciliul fiecăruia dintre părinţi, în care va conține, după caz, și informația disponibilă privind actele de violență în această familie și persoana agresorului familial.","lvl":1},{"k":"al","n":"4","id":"a4","t":"În cazul în care lipsește acordul părinților cu privire la stabilirea domiciliului copilului, până la stabilirea acestuia de către instanța de judecată, domiciliul copilului este considerat domiciliul părintelui cu care acesta locuiește permanent.","lvl":1},{"k":"al","n":"5","id":"a5","t":"În cazul indicat la alin. (4), părintele care locuiește separat de copil are dreptul să petreacă timpul cu copilul la domiciliul său, dacă aceasta nu contravine interesului superior al copilului, luându-se în considerație vârsta copilului, proximitatea domiciliului părintelui care locuiește separat, frecventarea studiilor/participarea la activități extrașcolare, conform unui program stabilit de autoritatea tutelară teritorială.","lvl":1,"r":[[20,29,{"al":"4","art":"63"}]]}]},{"id":"64","num":"64","title":"Exercitarea drepturilor părintești de către părintele care locuiește separat de copil","node":"n14","blocks":[{"k":"al","n":"1","id":"a1","t":"În cazul în care părinții locuiesc separat, părintele care locuiește împreună cu copilul nu poate împiedica exercitarea drepturilor părintești de către părintele care locuiește separat, inclusiv menținerea relațiilor personale regulate și a contactului direct cu copilul, cu excepția cazurilor în care contactul a fost limitat sau suspendat, în condițiile legii, pentru o perioadă determinată, iar menținerea contactului contravine interesului superior al copilului ori pune în pericol viața, sănătatea sau dezvoltarea copilului.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Părinții au dreptul să încheie un acord privind modalitatea de exercitare a drepturilor și de îndeplinire a obligațiilor părintești de către părintele care locuiește separat de copil, cu respectarea interesului superior al copilului. Dacă copilul este capabil să își formeze propria opinie, acestuia i se oferă posibilitatea de a și-o exprima, iar de opinia copilului se ține cont în conformitate cu vârsta și gradul său de maturitate.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Pentru soluționarea neînțelegerilor privind exercitarea drepturilor părintești și stabilirea programului de întrevederi, părinții pot recurge la mediere, din proprie inițiativă, dacă medierea nu contravine interesului superior al copilului și dacă nu sunt constatate acte de violență, abuz, neglijare, intimidare ori alte riscuri pentru copil.","lvl":1},{"k":"al","n":"4","id":"a4","t":"În lipsa acordului prevăzut la alin. (2), programul de întrevederi ale copilului cu părintele care locuiește separat se stabilește de către autoritatea tutelară teritorială de la locul aflării copilului, cu respectarea interesului superior al acestuia.","lvl":1,"r":[[31,40,{"al":"2","art":"64"}]]},{"k":"al","n":"5","id":"a5","t":"La stabilirea programului de întrevederi, autoritatea tutelară teritorială examinează toate circumstanțele privind situația copilului, inclusiv vârsta acestuia, atașamentul față de fiecare dintre părinți, relațiile copilului cu fiecare părinte, precum și cu frații și surorile, frecventarea studiilor și participarea la activități extrașcolare, proximitatea domiciliului părintelui care locuiește separat, opinia copilului, de care se ține cont în conformitate cu vârsta și gradul său de maturitate, precum și alte circumstanțe importante pentru asigurarea protecției interesului superior al copilului.","lvl":1},{"k":"al","n":"6","id":"a6","t":"Programul de întrevederi stabilit prin decizia autorității tutelare teritoriale se supune confirmării de către instanța judecătorească, în condițiile Codului de procedură civilă nr. 225/2003.","lvl":1,"r":[[150,190,{"a":"cod:procedura civila","whole":true}]]},{"k":"al","n":"7","id":"a7","t":"Programul de întrevederi confirmat de instanța judecătorească poate fi modificat la cererea unuia dintre părinți sau a autorității tutelare teritoriale dacă de la data emiterii încheierii privind confirmarea programului de întrevederi au trecut cel puțin 6 luni și dacă s-au modificat circumstanțele care au stat la baza stabilirii acestuia. Cererea de modificare poate fi depusă înainte de expirarea termenului de 6 luni dacă modificarea este impusă de interesul superior al copilului, în cazul emiterii unei ordonanțe de protecție după confirmarea programului de întrevederi ori în cazul apariției unor riscuri pentru viața, sănătatea, siguranța sau dezvoltarea copilului.","lvl":1},{"k":"al","n":"8","id":"a8","t":"În cazul în care părintele la domiciliul căruia a fost stabilit domiciliul copilului pleacă temporar în altă localitate, din țară sau de peste hotare, iar copilul rămâne în grija altei persoane, părintele care locuiește separat de copil își păstrează dreptul de a menține relații personale și contact direct cu copilul, inclusiv dreptul de a vizita copilul, conform programului de întrevederi stabilit în condițiile legii, dacă acestea nu contravin interesului superior al copilului și nu aduc atingere măsurilor de protecție dispuse potrivit legii.","lvl":1},{"k":"al","n":"9","id":"a9","t":"În cazul în care părintele la domiciliul căruia a fost stabilit domiciliul copilului pleacă împreună cu copilul în altă localitate, din țară sau de peste hotare, acesta este obligat să asigure menținerea relațiilor personale ale copilului cu celălalt părinte, inclusiv prin mijloace de comunicare la distanță, precum și posibilitatea exercitării dreptului la întrevederi stabilit în condițiile legii, în măsura în care acestea nu contravin interesului superior al copilului și nu aduc atingere măsurilor de protecție dispuse potrivit legii.","lvl":1},{"k":"al","n":"10","id":"a10","t":"Neexecutarea intenționată și repetată a programului de întrevederi stabilit în condițiile legii, constatată prin procese-verbale întocmite de executorul judecătoresc, poate constitui drept temei pentru solicitarea modificării domiciliului copilului, dacă măsura în cauză este necesară, proporțională și corespunde interesului superior al copilului.","lvl":1},{"k":"al","n":"11","id":"a11","t":"Executarea programului de întrevederi se realizează de către executorul judecătoresc, în condițiile Codului de executare nr. 443/2004.","lvl":1,"r":[[100,133,{"a":"cod:executare","whole":true}]]},{"k":"al","n":"12","id":"a12","t":"Părintele care locuiește separat de copil are dreptul de a primi informații cu privire la copilul său de la toate instituțiile de învățământ, cele curative și cele de asistență socială, precum și de la alte instituții. Comunicarea informației poate fi refuzată dacă comportamentul părintelui prezintă pericol pentru viața și sănătatea copilului. Refuzul în cauză poate fi atacat în instanța judecătorească.","lvl":1},{"k":"al","n":"13","id":"a13","t":"Programul de întrevederi stabilit prin hotărâre definitivă și irevocabilă a unei instanțe judecătorești din alt stat sau, după caz, prin actul administrativ al unei autorități competente din alt stat se prezintă autorității tutelare teritoriale de la locul aflării copilului, care îl remite instanței judecătorești spre confirmare, în condițiile procedurii prevăzute de Codul de procedură civilă nr. 225/2003, aplicată în mod corespunzător.","lvl":1,"r":[[370,408,{"a":"cod:procedura civila","whole":true}]]},{"k":"note","t":"[Art. 64 în redacția LP126 din 02.07.26, MO359-362/06.08.26 art. 361; în vigoare 06.08.26]","id":"n1","lvl":0}]},{"id":"65","num":"65","title":"Relațiile personale ale copilului cu bunicii, frații și surorile","node":"n14","blocks":[{"k":"al","n":"1","id":"a1","t":"Copilul are dreptul de a menține relații personale și de a comunica cu bunicii, frații și surorile, iar aceștia au dreptul de a menține relații personale cu copilul, dacă aceasta corespunde interesului superior al copilului.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Părinții sau, după caz, reprezentantul legal al copilului nu poate împiedica în mod nejustificat menținerea relațiilor personale ale copilului cu bunicii, frații și surorile.","lvl":1},{"k":"al","n":"3","id":"a3","t":"În cazul în care menținerea relațiilor personale prevăzute la alin. (1) este împiedicată, autoritatea tutelară teritorială, la cererea persoanei interesate, examinează situația copilului și stabilește un program de întrevederi, dacă aceasta corespunde interesului superior al copilului.","lvl":1,"r":[[62,71,{"al":"1","art":"65"}]]},{"k":"al","n":"4","id":"a4","t":"La stabilirea programului de întrevederi, autoritatea tutelară teritorială examinează vârsta copilului, relațiile acestuia cu bunicii, frații și surorile, precum și opinia copilului, de care se ține cont în conformitate cu vârsta și gradul său de maturitate, precum și alte circumstanțe importante pentru determinarea interesului superior al copilului.","lvl":1},{"k":"al","n":"5","id":"a5","t":"În cazul în care sunt constatate acte de violență, abuz, neglijare, intimidare sau alte riscuri pentru copil, acestea se iau în considerare la stabilirea programului de întrevederi, astfel încât exercitarea acestui drept să nu pună în pericol viața, sănătatea sau dezvoltarea copilului.","lvl":1},{"k":"al","n":"6","id":"a6","t":"Programul de întrevederi stabilit de autoritatea tutelară teritorială se supune confirmării de către instanța judecătorească, în condițiile procedurii prevăzute de Codul de procedură civilă nr. 225/2003, aplicată în mod corespunzător.","lvl":1,"r":[[164,202,{"a":"cod:procedura civila","whole":true}]]},{"k":"al","n":"7","id":"a7","t":"Programul de întrevederi confirmat de către instanța judecătorească poate fi modificat la cererea bunicilor, fraților sau a surorilor copilului, a unuia dintre părinți, a reprezentantului legal al copilului ori a autorității tutelare teritoriale dacă de la data pronunțării încheierii privind confirmarea modalității de comunicare sau a programului de întrevederi au trecut cel puțin 6 luni și dacă s-au modificat circumstanțele care au stat la baza stabilirii acestuia. Cererea de modificare poate fi depusă înainte de expirarea termenului de 6 luni dacă modificarea este impusă de interesul superior al copilului, în cazul emiterii unei ordonanțe de protecție după confirmarea programului de întrevederi ori în cazul apariției unor riscuri pentru viața, sănătatea, siguranța sau dezvoltarea copilului.","lvl":1},{"k":"al","n":"8","id":"a8","t":"Executarea programului de întrevederi se realizează de către executorul judecătoresc, în condițiile Codului de executare nr. 443/2004.","lvl":1,"r":[[100,133,{"a":"cod:executare","whole":true}]]},{"k":"note","t":"[Art. 65 în redacția LP126 din 02.07.26, MO359-362/06.08.26 art. 361; în vigoare 06.08.26]","id":"n1","lvl":0}]},{"id":"66","num":"66","title":"Apărarea drepturilor părinteşti","node":"n14","blocks":[{"k":"al","n":"1","id":"a1","t":"Părinţii au dreptul să ceară înapoierea copilului de la orice persoană care îl reţine fără un temei legal. În caz de litigiu, părinţii se pot adresa instanţei judecătoreşti.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Instanţa judecătorească este în drept să respingă acţiunea prevăzută la alin.(1) dacă va stabili că înapoierea copilului părinţilor săi contravine intereselor acestuia.","lvl":1,"r":[[72,80,{"al":"1","art":"66"}]]},{"k":"al","n":"3","id":"a3","t":"Dacă instanţa judecătorească va stabili că nici părinţii şi nici persoanele la care se află copilul nu sînt în stare să asigure întreţinerea, educaţia şi dezvoltarea adecvată a acestuia, ea va obliga autoritatea tutelară teritorială să dispună plasamentul copilului în conformitate cu prevederile Legii nr. 140/2013 privind protecţia specială a copiilor aflaţi în situaţii de risc şi a copiilor separaţi de părinţi.","lvl":1,"r":[[297,315,{"a":"lege:140/2013","whole":true}]]}]},{"id":"67","num":"67","title":"Decăderea din drepturile părinteşti","node":"n14","blocks":[{"k":"p","id":"x1","t":"Părinţii pot fi decăzuţi din drepturile părinteşti dacă:","lvl":1},{"k":"lit","n":"a","id":"la","t":"se eschivează de la exercitarea obligaţiilor părinteşti, inclusiv de la plata pensiei de întreţinere;","lvl":1},{"k":"lit","n":"b","id":"lb","t":"refuză să ia copilul din maternitate sau dintr-o altă instituţie curativă, educativă, dintr-o instituţie de asistenţă socială sau alta similară;","lvl":1},{"k":"lit","n":"c","id":"lc","t":"fac abuz de drepturile părinteşti;","lvl":1},{"k":"lit","n":"d","id":"ld","t":"se comportă cu cruzime faţă de copil, aplicând violenţa fizică sau psihică, atentează la inviolabilitatea sexuală a copilului;","lvl":1},{"k":"lit","n":"e","id":"le","t":"prin comportare amorală, influenţează negativ asupra copilului;","lvl":1},{"k":"lit","n":"f","id":"lf","t":"suferă de alcoolism cronic sau de narcomanie;","lvl":1},{"k":"lit","n":"g","id":"lg","t":"au săvârșit infracţiuni premeditate contra vieţii şi sănătăţii copiilor sau a soţului; precum şi","lvl":1},{"k":"lit","n":"h","id":"lh","t":"în alte cazuri când aceasta o cer interesele copilului.","lvl":1}]},{"id":"68","num":"68","title":"Modalitatea de decădere din drepturile părinteşti","node":"n14","blocks":[{"k":"al","n":"1","id":"a1","t":"Decăderea din drepturile părinteşti are loc numai pe cale judecătorească.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Acţiunea privind decăderea din drepturile părinteşti poate fi pornită de celălalt părinte, tutorele copilului, autoritatea tutelară teritorială.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Cererea privind decăderea din drepturile părinteşti se examinează cu participarea obligatorie a autorităţii tutelare teritoriale.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Instanţa judecătorească este obligată să transmită, în termen de 3 zile din momentul când hotărârea privind decăderea din drepturile părinteşti a rămas definitivă, o copie a acesteia organului stare civilă din raza teritorială a instanţei.","lvl":1}]},{"id":"69","num":"69","title":"Efectele decăderii din drepturile părinteşti","node":"n14","blocks":[{"k":"al","n":"1","id":"a1","t":"Copilul ai cărui părinţi (unul dintre ei) sînt decăzuţi din drepturile părinteşti păstrează dreptul de folosinţă asupra spaţiului locativ şi toate drepturile patrimoniale bazate pe rudenia cu părinţii şi rudele sale fireşti, inclusiv dreptul la succesiune.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Copiii ai căror părinţi/al căror unic părinte sînt decăzuţi/este decăzut din drepturile părinteşti sînt plasaţi în servicii de plasament în baza dispoziţiei autorităţii tutelare teritoriale.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Părinții decăzuți din drepturile părintești pot avea întrevederi cu copilul lor doar cu permisiunea autorității tutelare teritoriale, fiind luată în considerare, în mod obligatoriu, opinia copilului, în conformitate cu vârsta și gradul său de maturitate. Întrevederile nu se acordă dacă contactul părinţilor cu copilul poate cauza daune dezvoltării lui fizice sau intelectuale, dacă este evident că părinţii nu sînt capabili de acest contact, dacă, din anumite motive, contactul contravine intereselor copilului sau dacă acesta, în timpul dezbaterilor judiciare, a avut obiecţii serioase privind contactul cu părinţii decăzuţi din drepturi.","lvl":1}]},{"id":"70","num":"70","title":"Restabilirea drepturilor părinteşti","node":"n14","blocks":[{"k":"al","n":"1","id":"a1","t":"Părinţii pot fi restabiliţi în drepturile părinteşti dacă au încetat împrejurările care au condus la decăderea lor din aceste drepturi şi dacă restabilirea în drepturile părinteşti este în interesul copilului.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Restabilirea în drepturile părinteşti se face pe cale judecătorească, în baza cererii persoanei decăzute din aceste drepturi, cu participarea obligatorie a autorităţii tutelare teritoriale.","lvl":1},{"k":"al","n":"3","id":"a3","t":"La restabilirea în drepturile părintești se ține cont, în mod obligatoriu, de opinia copilului, în conformitate cu vârsta și gradul său de maturitate.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Dacă copilul a fost adoptat şi adopţia nu a fost desfăcută, hotărârea privind decăderea din drepturile părinteşti poate fi anulată fără restabilirea drepturilor şi obligaţiilor de părinte.","lvl":1}]},{"id":"71","num":"71","title":"Luarea copilului fără decădere din drepturile părinteşti","node":"n14","blocks":[{"k":"al","n":"1","id":"a1","t":"La cererea autorităţii tutelare, instanţa judecătorească poate hotărî luarea copilului de la părinţi fără decăderea acestora din drepturile părinteşti, dacă aflarea copilului împreună cu părinţii prezintă pericol pentru viaţa şi sănătatea lui, şi asigurarea protecţiei copilului de către autoritatea tutelară teritorială.","lvl":1},{"k":"al","n":"2","id":"a2","t":"În cazuri excepţionale, dacă există un pericol iminent pentru viaţa, sănătatea sau inviolabilitatea copilului, autoritatea tutelară poate decide luarea copilului de la părinţi, comunicând acest fapt procurorului în termen de cel mult 24 de ore.","lvl":1},{"k":"al","n":"3","id":"a3","t":"În cazurile prevăzute la alin.(2), autoritatea tutelară, în termen de 3 zile lucrătoare, va porni o acţiune în instanţa judecătorească privind decăderea din drepturile părinteşti sau luarea copilului de la părinţi fără decăderea lor din aceste drepturi. Dacă această cerinţă nu este îndeplinită, copilul va fi înapoiat părinţilor.","lvl":1,"r":[[25,33,{"al":"2","art":"71"}]]},{"k":"al","n":"4","id":"a4","t":"Cererea privind luarea copilului de la părinţi fără decăderea acestora din drepturile părinteşti se examinează cu participarea obligatorie a autorităţii tutelare și a celei teritoriale, în a cărei evidenţă se află copilul.","lvl":1},{"k":"al","n":"5","id":"a5","t":"La cererea părinţilor, instanţa judecătorească poate să le înapoieze copilul dacă aceasta nu contravine intereselor copilului.","lvl":1}]},{"id":"72","num":"72","title":"Efectele luării copilului fără decădere din drepturile părinteşti","node":"n14","blocks":[{"k":"al","n":"1","id":"a1","t":"În cazurile luării copilului fără decădere din drepturile părinteşti, părinţii pierd dreptul de a comunica cu acesta, de a participa personal la educaţia lui şi de a-i reprezenta interesele, reprezentantul legal al copilului pentru perioada respectivă fiind autoritatea tutelară teritorială.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Părinţii de la care a fost luat copilul pot avea întrevederi cu acesta, în unele cazuri, cu permisiunea autorităţii tutelare în a cărei evidentă se află copilul și în baza avizului pozitiv al autorităţii tutelare în a cărei rază locuiesc părinții copilului, fiind luată în considerare, în mod obligatoriu, opinia copilului, în conformitate cu vârsta și gradul său de maturitate.","lvl":1}]},{"id":"73","num":"73","title":"Participarea autorității tutelare teritoriale la examinarea cauzelor privind creșterea, educația și protecția copilului","node":"n14","blocks":[{"k":"al","n":"1","id":"a1","t":"La examinarea de către instanța judecătorească a cauzelor privind creșterea, educația și protecția copilului în cadrul procedurii de confirmare a programului de întrevederi, precum și la executarea hotărârilor și încheierilor judecătorești emise în cauzele respective, participarea autorității tutelare teritoriale este obligatorie.","lvl":1},{"k":"al","n":"2","id":"a2","t":"În cadrul procedurii de confirmare a programului de întrevederi, autoritatea tutelară teritorială prezintă instanței judecătorești decizia privind stabilirea programului de întrevederi, avizul motivat și materialele care au stat la baza adoptării deciziei respective.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Autoritatea tutelară teritorială examinează condițiile de trai ale copilului, situația acestuia, relațiile cu părinții și cu alte persoane relevante, opinia copilului, de care se ține cont în conformitate cu vârsta și gradul său de maturitate, precum și alte circumstanțe importante pentru determinarea interesului superior al copilului. În baza constatărilor efectuate în cadrul examinării, autoritatea tutelară teritorială prezintă instanței judecătorești un aviz motivat.","lvl":1},{"k":"al","n":"4","id":"a4","t":"În cazul în care sunt constatate acte de violență, abuz, neglijare, intimidare sau alte riscuri pentru copil, acestea se reflectă în mod expres în avizul prevăzut la alin. (3).","lvl":1,"r":[[166,175,{"al":"3","art":"73"}]]},{"k":"al","n":"5","id":"a5","t":"În vederea întocmirii avizului prevăzut la alin. (3), autoritatea tutelară teritorială poate solicita informații și documente de la autoritățile publice, instituțiile de învățământ, instituțiile medico-sanitare și de la alte entități competente, în condițiile legii.","lvl":1,"r":[[43,52,{"al":"3","art":"73"}]]},{"k":"al","n":"6","id":"a6","t":"Modul de întocmire a avizului prevăzut la alin. (3), conținutul acestuia și procedura de cooperare dintre autoritatea tutelară teritorială și alte autorități publice se stabilesc de Guvern.","lvl":1,"r":[[42,51,{"al":"3","art":"73"}]]},{"k":"note","t":"[Art. 73 în redacția LP126 din 02.07.26, MO359-362/06.08.26 art. 361; în vigoare 06.08.26]","id":"n1","lvl":0}]},{"id":"73_1","num":"73¹","title":"Conflictul de interese între o parte interesată și autoritatea tutelară","node":"n14","blocks":[{"k":"p","id":"x1","t":"În cazul unui conflict de interese între o parte interesată și autoritatea tutelară sau cea teritorială, la cererea părții interesate, instanța judecătorească poate desemna responsabilă de caz o altă autoritate tutelară teritorială, ținând cont de criteriul proximității, precum și de alte criterii relevante.","lvl":1}]},{"id":"74","num":"74","title":"Obligaţia părinţilor de a-şi întreţine copiii","node":"n16","blocks":[{"k":"al","n":"1","id":"a1","t":"Părinţii sînt obligaţi să-şi întreţină copiii minori şi copiii majori inapţi de muncă care necesită sprijin material.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Modul de plată a pensiei de întreţinere se determină în baza unui contract încheiat între părinţi sau între părinţi şi copilul major inapt de muncă.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Dacă lipseşte un atare contract şi părinţii nu participă la întreţinerea copiilor, pensia de întreţinere se încasează pe cale judecătorească, la cererea unuia dintre părinţi, a tutorelui copilului sau a autorităţii tutelare teritoriale.","lvl":1}]},{"id":"75","num":"75","title":"Cuantumul pensiei de întreţinere încasate pentru copilul minor","node":"n16","blocks":[{"k":"al","n":"1","id":"a1","t":"Pensia de întreţinere pentru copilul minor se încasează din salariul şi/sau din alte venituri ale părinţilor în mărime de 1/4 - pentru un copil, 1/3 - pentru 2 copii şi 1/2 - pentru 3 şi mai mulţi copii.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Cuantumul cotelor stabilite la alin.(1) poate fi micşorat sau majorat de instanţa judecătorească, ţinându-se cont de starea materială şi familială a părinţilor, de alte circumstanţe importante.","lvl":1,"r":[[31,39,{"al":"1","art":"75"}]]},{"k":"al","n":"3","id":"a3","t":"În cazul în care unii copii rămân cu un părinte, iar alţii - cu celălalt, pensia de întreţinere plătită în favoarea părintelui mai puţin asigurat se stabileşte într-o sumă bănească fixă, determinată conform art.76.","lvl":1,"r":[[207,213,{"art":"76"}]]}]},{"id":"76","num":"76","title":"Încasarea pensiei de întreţinere pentru copilul minor într-o sumă bănească fixă","node":"n16","blocks":[{"k":"al","n":"1","id":"a1","t":"În cazurile când părintele care datorează întreţinere copilului său are un salariu şi/sau alte venituri neregulate sau fluctuabile ori primeşte salariu şi/sau alte venituri, total sau parţial, în natură, ori nu are un salariu şi/sau alte venituri, precum şi în alte cazuri când, din anumite motive, încasarea pensiei de întreţinere, sub forma unei cote din salariu şi/sau alte venituri, este imposibilă, dificilă sau lezează substanțial interesele uneia dintre părţi, instanţa judecătorească poate să stabilească cuantumul pensiei de întreţinere într-o sumă bănească fixă plătită lunar sau, concomitent, într-o sumă bănească fixă şi sub forma unei cote din salariu şi/sau alte venituri conform art.75.","lvl":1,"r":[[694,700,{"art":"75"}]]},{"k":"al","n":"2","id":"a2","t":"Cuantumul sumei băneşti fixe încasate în conformitate cu alin. (1) se determină de instanţa judecătorească, ţinându-se cont de starea materială şi familială a părţilor, de alte circumstanţe importante, cu respectarea prevederilor art. 108 şi păstrându-se, dacă este posibil, nivelul anterior de asigurare materială a copilului.","lvl":1,"r":[[57,66,{"al":"1","art":"76"}],[230,238,{"art":"108"}]]}]},{"id":"77","num":"77","title":"abrogat.","node":"n16","blocks":[],"abrogat":true},{"id":"78","num":"78","title":"Dreptul copiilor majori inapţi de muncă la pensie de întreţinere","node":"n16","blocks":[{"k":"al","n":"1","id":"a1","t":"Părinţii sînt obligaţi să-şi întreţină copiii majori inapţi de muncă care necesită sprijin material.","lvl":1},{"k":"al","n":"2","id":"a2","t":"În caz de litigii privind achitarea pensiei de întreţinere, instanţa judecătorească stabileşte cuantumul acesteia pentru copiii majori inapţi de muncă într-o sumă bănească fixă plătită lunar, ţinându-se cont de starea materială şi familială, de alte circumstanţe importante, cu respectarea prevederilor art. 108.","lvl":1,"r":[[303,311,{"art":"108"}]]}]},{"id":"79","num":"79","title":"Participarea părinţilor la cheltuielile suplimentare în favoarea copiilor","node":"n16","blocks":[{"k":"al","n":"1","id":"a1","t":"În caz de litigii şi de circumstanţe excepţionale (boală gravă, mutilare a copilului minor sau a celui major inapt de muncă, necesitatea achitării cheltuielilor privind îngrijirea acestora etc.), în lipsa contractului între părţi, instanţa judecătorească poate obliga pe fiecare dintre părinţi să participe la cheltuielile suplimentare generate de aceste circumstanţe.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Modalitatea participării părinţilor la cheltuielile suplimentare, precum şi cuantumul acestor cheltuieli sînt stabilite de instanţa judecătorească, ţinându-se cont de starea materială şi familială a părinţilor şi copiilor şi de alte circumstanţe importante. Cuantumul cheltuielilor suplimentare se stabileşte într-o sumă bănească fixă, ce va fi achitată lunar.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Instanţa judecătorească poate obliga părinţii să participe la cheltuielile suplimentare deja făcute, precum şi la viitoarele cheltuieli suplimentare.","lvl":1}]},{"id":"80","num":"80","title":"Obligaţia copiilor majori de a-şi întreţine părinţii","node":"n16","blocks":[{"k":"al","n":"1","id":"a1","t":"Copiii majori apţi de muncă sînt obligaţi să-şi întreţină şi să-şi îngrijească părinţii inapţi de muncă care necesită sprijin material.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Dacă nu există un contract privind întreţinerea părinţilor inapţi de muncă care necesită sprijin material, problema achitării pensiei de întreţinere de către copiii majori se soluţionează pe cale judecătorească.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Cuantumul pensiei de întreţinere se stabileşte de instanţa judecătorească într-o sumă bănească fixă plătită lunar, ţinându-se cont de starea materială şi familială a părinţilor şi a copiilor, de alte circumstanţe importante, cu respectarea prevederilor art. 108.","lvl":1,"r":[[253,261,{"art":"108"}]]},{"k":"al","n":"4","id":"a4","t":"La stabilirea cuantumului pensiei, instanţa judecătorească este în drept să ţină cont de toţi copiii majori ai părintelui respectiv, indiferent de faptul dacă acţiunea a fost pornită faţă de unul, câțiva sau toţi copiii.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Copilul poate fi eliberat de obligaţia de a-şi întreţine părinţii inapţi de muncă care necesită sprijin material dacă instanţa judecătorească va stabili că aceştia s-au eschivat de la îndeplinirea obligaţiilor părinteşti faţă de acest copil.","lvl":1},{"k":"al","n":"6","id":"a6","t":"Copiii ai căror părinţi sînt decăzuţi din drepturile părinteşti se scutesc de obligaţia de întreţinere a acestora.","lvl":1}]},{"id":"81","num":"81","title":"Participarea copiilor majori la cheltuielile suplimentare în favoarea părinţilor","node":"n16","blocks":[{"k":"al","n":"1","id":"a1","t":"În circumstanţe excepţionale (boală gravă, dizabilitate severă sau accentuată, mutilare sau alt viciu al părintelui etc.), copiii majori pot fi obligaţi de către instanţa judecătorească să participe la cheltuielile suplimentare generate de aceste circumstanţe dacă lipseşte un contract între părţi sau dacă copiii refuză să participe benevol la aceste cheltuieli.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Modul de participare a copiilor majori la cheltuielile suplimentare în favoarea părinţilor şi cuantumul acestora se determină de instanţa judecătorească, conform dispoziţiilor art.80.","lvl":1,"r":[[176,182,{"art":"80"}]]},{"k":"al","n":"3","id":"a3","t":"Instanţa judecătorească este în drept să elibereze copiii majori de participarea la cheltuielile suplimentare în favoarea părinţilor dacă se va stabili că aceştia s-au eschivat de la îndeplinirea obligaţiilor părinteşti faţă de aceşti copii, chiar şi în cazul când copiii plătesc pensia de întreţinere.","lvl":1}]},{"id":"82","num":"82","title":"Obligaţia soţilor de a se întreţine reciproc","node":"n17","blocks":[{"k":"al","n":"1","id":"a1","t":"Soţii îşi datorează întreţinerea materială reciprocă.","lvl":1},{"k":"al","n":"2","id":"a2","t":"În cazul refuzului de a acorda întreţinere şi dacă între soţi nu există un contract privind plata pensiei de întreţinere, dreptul de a porni o acţiune în instanţa judecătorească privind încasarea acesteia de la celălalt soţ îl au:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"soţul inapt de muncă (care a atins vârsta de pensionare sau este persoană cu dizabilitate severă, accentuată sau medie) şi care necesită sprijin material;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"soţia în timpul gravidităţii;","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"soţul care îngrijeşte copilul comun timp de 3 ani după naşterea acestuia;","lvl":2},{"k":"lit","n":"d","id":"a2.ld","t":"soţul care îngrijeşte pînă la vârsta de 18 ani un copil comun cu dizabilităţi sau care îngrijeşte un copil comun cu dizabilități severe din copilărie, dacă acest soţ nu lucrează şi copilul necesită îngrijire.","lvl":2},{"k":"al","n":"3","id":"a3","t":"Pensia de întreţinere se plăteşte persoanelor enumerate la alin.(2) numai în cazul când acestea nu au un venit propriu suficient, iar soţul care datorează întreţinere are posibilitatea de a o plăti.","lvl":1,"r":[[59,67,{"al":"2","art":"82"}]]}]},{"id":"83","num":"83","title":"Dreptul fostului soţ la întreţinere după divorţ","node":"n17","blocks":[{"k":"p","id":"x1","t":"Dreptul de a pretinde întreţinere de la fostul soţ pe cale judecătorească îl are:","lvl":1},{"k":"lit","n":"a","id":"la","t":"fosta soţie în timpul gravidităţii;","lvl":1},{"k":"lit","n":"b","id":"lb","t":"fostul soţ, care necesită sprijin material, ocupat cu îngrijirea copilului comun timp de 3 ani după naşterea acestuia;","lvl":1},{"k":"lit","n":"c","id":"lc","t":"fostul soţ, care necesită sprijin material, ocupat cu îngrijirea copilului comun cu dizabilităţi pînă la vârsta de 18 ani sau a copilului comun cu dizabilități severe din copilărie;","lvl":1},{"k":"lit","n":"d","id":"ld","t":"fostul soţ, care necesită sprijin material, devenit inapt de muncă în timpul căsătoriei sau timp de un an după desfacerea acesteia;","lvl":1},{"k":"lit","n":"e","id":"le","t":"fostul soţ care necesită sprijin material şi a atins vârsta de pensionare, în termen de cel mult 5 ani din momentul desfacerii căsătoriei, dacă soţii au fost căsătoriţi cel puţin 15 ani.","lvl":1}]},{"id":"84","num":"84","title":"Cuantumul pensiei de întreţinere încasate de la soţ (fostul soţ)","node":"n17","blocks":[{"k":"p","id":"x1","t":"Cuantumul pensiei de întreţinere încasate de la un soţ (fost soţ) în favoarea celuilalt soţ se stabileşte de către instanţa judecătorească într-o sumă bănească fixă plătită lunar. La stabilirea sumei pensiei de întreţinere, se ţine cont de situaţia materială şi familială a soţilor (foştilor soţi), de alte circumstanţe importante, cu respectarea prevederilor art. 108.","lvl":1,"r":[[360,368,{"art":"108"}]]}]},{"id":"85","num":"85","title":"Scutirea soţului (fostului soţ) de obligaţia de întreţinere sau limitarea în termen a acestei obligaţii","node":"n17","blocks":[{"k":"p","id":"x1","t":"Instanţa judecătorească este în drept să-l elibereze pe unul dintre soţi (fostul soţ) de obligaţia de întreţinere sau să limiteze această obligaţie la un anumit termen dacă:","lvl":1},{"k":"lit","n":"a","id":"la","t":"incapacitatea de muncă a soţului (fostului soţ) inapt de muncă, care necesită sprijin material, este rezultatul abuzului de băuturi alcoolice sau substanţe stupefiante ori al unei infracţiuni premeditate;","lvl":1},{"k":"lit","n":"b","id":"lb","t":"soţul (fostul soţ) care necesită sprijin material a avut o comportare amorală în familie;","lvl":1},{"k":"lit","n":"c","id":"lc","t":"soţii (foştii soţi) s-au aflat în relaţii de căsătorie cel mult 5 ani;","lvl":1},{"k":"lit","n":"d","id":"ld","t":"s-a dovedit, pe cale judecătorească, că căsătoria a fost desfăcută din culpa fostului soţ care necesită sprijin material.","lvl":1}]},{"id":"86","num":"86","title":"Obligaţia de întreţinere dintre fraţi şi surori","node":"n18","blocks":[{"k":"al","n":"1","id":"a1","t":"Fraţii şi surorile minore, care necesită sprijin material, în imposibilitatea întreţinerii lor de către părinţi, au dreptul la întreţinere de la surorile şi fraţii majori apţi de muncă care dispun de mijloace suficiente.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Acelaşi drept îl au surorile şi fraţii majori inapţi de muncă, care necesită sprijin material, dacă s-a stabilit imposibilitatea întreţinerii acestora de către copiii lor majori apţi de muncă, de către soţi (foştii soţi) sau de către părinţi.","lvl":1}]},{"id":"87","num":"87","title":"Obligaţia bunicilor de a-şi întreţine nepoţii","node":"n18","blocks":[{"k":"al","n":"1","id":"a1","t":"Nepoţii minori, care necesită sprijin material, în imposibilitatea întreţinerii lor de către părinţi, au dreptul la întreţinere de la bunicii - care dispun de mijloace suficiente.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Acelaşi drept îl au şi nepoţii majori inapţi de muncă, care necesită sprijin material, dacă s-a stabilit imposibilitatea întreţinerii lor de către soţi (foştii soţi), copiii majori apţi de muncă sau de către părinţi.","lvl":1}]},{"id":"88","num":"88","title":"Obligaţia nepoţilor de a-şi întreţine bunicii","node":"n18","blocks":[{"k":"p","id":"x1","t":"Bunicii inapţi de muncă, care necesită sprijin material, în imposibilitatea întreţinerii lor de către copiii majori apţi de muncă sau de către soţi (foştii soţi), au dreptul la întreţinere de la nepoţii majori apţi de muncă care dispun de mijloace suficiente.","lvl":1}]},{"id":"89","num":"89","title":"Obligaţia copiilor vitregi de a-şi întreţine părinţii vitregi","node":"n18","blocks":[{"k":"al","n":"1","id":"a1","t":". Părinţii vitregi inapţi de muncă, care necesită sprijin material, în imposibilitatea întreţinerii lor de către copiii lor fireşti majori apţi de muncă sau de către soţ (fostul soţ), au dreptul la întreţinere de la copiii vitregi majori apţi de muncă care dispun de mijloace suficiente.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Instanţa judecătorească este în drept să scutească copiii vitregi de obligaţia de a-şi întreţine părinţii vitregi dacă aceştia i-au întreţinut şi educat mai puţin de 5 ani sau nu şi-au onorat obligaţiile.","lvl":1}]},{"id":"90","num":"90","title":"Obligaţia copiilor de a-şi întreţine educatorii","node":"n18","blocks":[{"k":"al","n":"1","id":"a1","t":"Persoanele inapte de muncă, care necesită sprijin material, şi care au întreţinut şi educat copii minori (denumiţi în continuare educatori) au dreptul la întreţinere de la aceştia dacă ultimii au atins vârsta majoratului, sînt apţi de muncă şi dispun de mijloace suficiente şi dacă s-a stabilit imposibilitatea întreţinerii educatorilor de către propriii lor copii majori apţi de muncă sau de către soţ (fostul soţ).","lvl":1},{"k":"al","n":"2","id":"a2","t":"Instanţa judecătorească este în drept să scutească copiii de obligaţia de a-şi întreţine educatorii dacă aceştia i-au întreţinut şi educat mai puţin de 5 ani sau nu şi-au onorat obligaţiile.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Persoanele cărora li s-a stabilit statut de copil rămas temporar fără ocrotire părintească sau de copil rămas fără ocrotire părintească sunt scutite de obligațiile prevăzute la alin. (1).","lvl":1,"r":[[177,186,{"al":"1","art":"90"}]]}]},{"id":"91","num":"91","title":"Cuantumul şi modul de încasare a pensiei de întreţinere pentru alţi membri ai familiei","node":"n18","blocks":[{"k":"al","n":"1","id":"a1","t":"Cuantumul şi modul de încasare a pensiei de întreţinere pentru persoanele menţionate la art.86-90 pot fi stabilite printr-un contract între părţi.","lvl":1,"r":[[88,97,{"art":"86","art2":"90"}]]},{"k":"al","n":"2","id":"a2","t":"Dacă nu există un contract între părţi, pensia de întreţinere se stabileşte de către instanţa judecătorească în sumă bănească fixă achitată lunar, ţinându-se cont de starea materială şi familială a persoanei care datorează întreţinere şi a persoanei care are dreptul la întreţinere, precum şi de alte circumstanţe importante, cu respectarea prevederilor art. 108.","lvl":1,"r":[[354,362,{"art":"108"}]]},{"k":"al","n":"3","id":"a3","t":"Dacă unul dintre membrii familiei are dreptul la pensie de întreţinere concomitent de la mai multe persoane, instanţa judecătorească determină cuantumul acesteia pentru fiecare dintre cei ce o datorează, ținând cont de starea lor materială şi familială. Instanţa judecătorească este în drept să ia în considerare toate persoanele care datorează întreţinere, indiferent de faptul dacă acţiunea a fost pornită faţă de una, câteva sau toate persoanele în cauză.","lvl":1}]},{"id":"92","num":"92","title":"Contractul privind plata pensiei de întreţinere","node":"n19","blocks":[{"k":"p","id":"x1","t":"Contractul privind mărimea, condiţiile şi modul de plată a pensiei de întreţinere poate fi încheiat între persoana care datorează întreţinere (debitorul întreţinerii) şi persoana care are dreptul la întreţinere (creditorul întreţinerii).","lvl":1}]},{"id":"93","num":"93","title":"Forma contractului privind plata pensiei de întreţinere","node":"n19","blocks":[{"k":"p","id":"x1","t":"Contractul privind plata pensiei de întreţinere se întocmeşte în scris şi se autentifică notarial. Nerespectarea acestor prevederi atrage nulitatea contractului.","lvl":1}]},{"id":"94","num":"94","title":"Modul de încheiere, executare, modificare, reziliere şi declarare a nulităţii contractului privind plata pensiei de întreţinere","node":"n19","blocks":[{"k":"al","n":"1","id":"a1","t":"Contractul privind plata pensiei de întreţinere se încheie, se execută, se modifică, se reziliază şi se declară nul în conformitate cu normele Codului civil.","lvl":1,"r":[[143,156,{"a":"cod:civil","whole":true}]]},{"k":"al","n":"2","id":"a2","t":"Contractul privind plata pensiei de întreţinere poate fi, în orice moment, modificat sau reziliat în baza acordului dintre părţi. Modificarea sau rezilierea contractului se perfectează în scris şi se autentifică notarial.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Modificarea unilaterală a contractului privind plata pensiei de întreţinere sau refuzul unilateral de a-l executa sînt inadmisibile.","lvl":1},{"k":"al","n":"4","id":"a4","t":"În caz de modificare esenţială a situaţiei materiale sau familiale a părţilor, dacă acestea nu pot ajunge la o înţelegere referitoare la modificarea sau rezilierea contractului privind plata pensiei de întreţinere, partea interesată poate porni în instanţa judecătorească o acţiune privind modificarea sau rezilierea acestuia. Instanţa judecătorească soluţionează litigiul ținând cont de starea materială şi familială a părţilor, de alte circumstanţe importante.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Dacă contractul privind plata pensiei de întreţinere contravine intereselor copilului minor, acesta poate fi declarat nul de către instanţa judecătorească la cererea reprezentanţilor legali ai copilului sau a autorităţii tutelare teritoriale.","lvl":1}]},{"id":"95","num":"95","title":"Cuantumul pensiei de întreţinere stabilite prin contract","node":"n19","blocks":[{"k":"al","n":"1","id":"a1","t":"Cuantumul pensiei de întreţinere stabilite prin contract se determină de către părţi la încheierea contractului corespunzător.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Cuantumul pensiei de întreţinere pentru copiii minori prevăzut în contract nu poate fi mai mic decât cel stabilit la art.75.","lvl":1,"r":[[117,123,{"art":"75"}]]}]},{"id":"96","num":"96","title":"Modul de plată a pensiei de întreţinere stabilite prin contract","node":"n19","blocks":[{"k":"al","n":"1","id":"a1","t":"Modul de plată a pensiei de întreţinere stabilite prin contract se determină de către părţi la încheierea contractului corespunzător.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Pensia de întreţinere poate fi plătită sub forma unor cote-părţi din salariul şi/sau din alte venituri ale debitorului întreţinerii, într-o sumă bănească fixă plătită periodic, prin transmiterea unor bunuri sau într-un alt mod stipulat în contract.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Contractul privind plata pensiei de întreţinere poate stipula îmbinarea mai multor moduri de achitare a acesteia.","lvl":1}]},{"id":"97","num":"97","title":"Încasarea pensiei de întreţinere în baza hotărârii instanţei judecătoreşti","node":"n20","blocks":[{"k":"p","id":"x1","t":"În lipsa unui acord referitor la întreţinere, membrii familiei menţionaţi la art.74-91 pot porni în instanţa judecătorească o acţiune privind încasarea pensiei respective, chiar şi în cazul când aceasta, se plăteşte benevol.","lvl":1,"r":[[77,86,{"art":"74","art2":"91"}]]}]},{"id":"98","num":"98","title":"Termenul de pornire a acţiunii privind încasarea pensiei de întreţinere","node":"n20","blocks":[{"k":"al","n":"1","id":"a1","t":"Persoana care are dreptul la întreţinere poate porni o acţiune privind încasarea pensiei de întreţinere, indiferent de termenul care a trecut de la momentul apariţiei dreptului respectiv.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Pensia de întreţinere se încasează de la data adresării în instanţa judecătorească.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Pensia de întreţinere poate fi încasată pentru perioada anterioară adresării în instanţa judecătorească dacă se va stabili că în perioada respectivă s-au întreprins măsuri de acordare a întreţinerii, dar debitorul întreţinerii s-a eschivat de la plata pensiei.","lvl":1}]},{"id":"99","num":"99","title":"Încasarea pensiei de întreţinere pînă la soluţionarea litigiului în instanţa judecătorească","node":"n20","blocks":[{"k":"al","n":"1","id":"a1","t":"Instanţa judecătorească este în drept să hotărască încasarea pensiei de întreţinere de la data depunerii cererii.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Cuantumul pensiei de întreţinere se stabileşte în modul prevăzut de prezentul cod.","lvl":1},{"k":"al","n":"3","id":"a3","t":"În cazul în care cererea privind încasarea pensiei de întreţinere va fi respinsă sau pensia va fi stabilită într-un cuantum mai mic, plăţile anterioare sau cele excedentare nu se restituie.","lvl":1}]},{"id":"100","num":"100","title":"Obligaţia patronului de a reţine pensia de întreţinere","node":"n20","blocks":[{"k":"p","id":"x1","t":"Patronul este obligat să reţină lunar, în baza contractului privind plata pensiei de întreţinere, autentificat notarial, sau a titlului executoriu, sau a cererii debitorului întreţinerii, pensia de întreţinere din salariul şi/sau din alte venituri ale debitorului întreţinerii şi să o transmită sau să o transfere, din contul acestuia, creditorului întreţinerii într-un termen de cel mult 3 zile de la data fixată pentru plata salariului şi/sau a altor venituri.","lvl":1}]},{"id":"101","num":"101","title":"Reţinerea pensiei de întreţinere în baza contractului privind plata pensiei de întreţinere","node":"n20","blocks":[{"k":"p","id":"x1","t":"Reţinerea pensiei de întreţinere din salariu şi/sau din alte venituri în baza contractului privind plata pensiei de întreţinere, autentificat notarial, se admite şi în cazul când suma reţinerilor, în baza contractului şi a altor titluri executorii, depăşeşte 50 la sută din salariul şi/sau din alte venituri ale debitorului întreţinerii.","lvl":1}]},{"id":"102","num":"102","title":"Obligaţia debitorului întreţinerii de a comunica schimbarea locului său de muncă sau a domiciliului","node":"n20","blocks":[{"k":"al","n":"1","id":"a1","t":"Patronul este obligat să comunice, în termen de 3 zile, instanţei judecătoreşti despre concedierea persoanei debitor al întreţinerii.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Debitorul întreţinerii este obligat să comunice, în termen de 3 zile, instanţei judecătoreşti despre schimbarea locului său de muncă şi/sau a domiciliului.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Persoanele care nu respectă prevederile prezentului articol sînt trase la răspundere în modul stabilit de legislaţie.","lvl":1}]},{"id":"103","num":"103","title":"Urmărirea bunurilor debitorului întreţinerii","node":"n20","blocks":[{"k":"al","n":"1","id":"a1","t":"Dacă debitorul întreţinerii nu are salariu sau alte venituri, fie că acestea sînt insuficiente pentru a-şi onora obligaţia, pensia de întreţinere se va încasa din mijloacele băneşti depuse de către debitor în instituţiile financiare sau transmise organizaţiilor comerciale şi necomerciale, cu excepţia cazurilor când aceste mijloace le-au fost transmise în proprietate. Dacă debitorul nu dispune de astfel de mijloace băneşti sau dacă dispune de ele, dar acestea sînt insuficiente pentru a-şi onora obligaţia, pensia de întreţinere se va încasa din contul tuturor bunurilor mobile şi imobile ale debitorului care pot fi urmărite.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Urmărirea bunurilor şi a mijloacelor băneşti ale debitorului se face în modul prevăzut de legislaţia procesuală civilă.","lvl":1}]},{"id":"104","num":"104","title":"Determinarea restanţei la pensia de întreţinere","node":"n20","blocks":[{"k":"al","n":"1","id":"a1","t":"Pensia de întreţinere se încasează pentru perioada anterioară în baza contractului privind plata pensiei de întreţinere sau a titlului executoriu, în limitele a cel mult 3 ani din momentul prezentării contractului sau a titlului executoriu respectiv.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Dacă pensia de întreţinere nu s-a încasat din culpa debitorului întreţinerii, restanţa ei se reţine, prin derogare de la prevederile alin.(1), pentru toată perioada anterioară.","lvl":1,"r":[[133,141,{"al":"1","art":"104"}]]},{"k":"al","n":"3","id":"a3","t":"Suma restanţei se determină pornindu-se de la cuantumul pensiei de întreţinere stabilit de instanţa judecătorească sau de contractul corespunzător.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Suma restanţei la pensia de întreţinere pentru copiii minori se determină pornindu-se de la salariul şi/sau alte venituri ale debitorului.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Dacă debitorul nu a lucrat în perioada în care s-a format restanţa sau nu a prezentat actele ce confirmă salariul şi/sau alte venituri ale sale, cuantumul restanţei la pensia de întreţinere se determină de către executorul judecătoresc, pornindu-se de la salariul mediu pe ţară la data determinării restanţei. Dacă părţile nu sînt de acord cu suma restanţei calculate sau situaţia financiar-materială a debitorului nu permite achitarea în conformitate cu alin.(1), ele sînt în drept să se adreseze cu o cerere în judecată pentru a se stabili suma concretă a restanţei.","lvl":1,"r":[[455,463,{"al":"1","art":"104"}]]},{"k":"al","n":"6","id":"a6","t":"Suma restanţei la pensia de întreţinere poate fi contestată în modul stabilit de legislaţie.","lvl":1}]},{"id":"105","num":"105","title":"Scutirea de achitare a restanţei la pensia de întreţinere","node":"n20","blocks":[{"k":"al","n":"1","id":"a1","t":"În baza contractului privind plata pensiei de întreţinere, debitorul întreţinerii poate fi scutit de plata restanţei la pensie de întreţinere sau această restanţă poate fi micşorată, cu excepţia cazurilor când pensia se plăteşte copiilor minori.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Dacă starea materială şi familială a debitorului întreţinerii face imposibilă lichidarea restanţei la pensia de întreţinere, instanţa judecătorească, la cererea acestuia, în baza unor motive temeinice, este în drept să-l elibereze de plata restanţei respective sau s-o micşoreze.","lvl":1}]},{"id":"106","num":"106","title":"Răspunderea pentru nerespectarea termenelor de plată a pensiei de întreţinere","node":"n20","blocks":[{"k":"al","n":"1","id":"a1","t":"Dacă restanţa la pensia de întreţinere a rezultat din culpa persoanei obligate s-o achite în baza contractului privind plata pensiei de întreţinere, persoana în cauză va purta răspunderea în modul prevăzut de acest contract.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Dacă restanţa la pensia de întreţinere a rezultat din culpa persoanei obligate s-o achite în baza hotărârii instanţei judecătoreşti, persoana în cauză va plăti creditorului întreţinerii o penalitate în mărime de 0,1 la sută din suma restanţei pentru fiecare zi de întârziere.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Creditorul întreţinerii este în drept să ceară repararea daunei, cauzate prin întârzierea executării obligaţiei de întreţinere din culpa debitorului, dacă aceasta nu a fost acoperită prin plata de penalităţi.","lvl":1}]},{"id":"107","num":"107","title":"Inadmisibilitatea compensării şi reîncasării pensiei de întreţinere","node":"n20","blocks":[{"k":"al","n":"1","id":"a1","t":"Nu se admite compensarea sau reîncasarea pensiei de întreţinere cu excepţia cazurilor de:","lvl":1},{"k":"lit","n":"a","id":"a1.la","t":"anulare a hotărîrii instanţei judecătoreşti privind încasarea pensiei de întreţinere adoptate în baza actelor sau dovezilor false prezentate de creditor;","lvl":2},{"k":"lit","n":"b","id":"a1.lb","t":"declarare a nulităţii contractului privind plata pensiei de întreţinere încheiat ca urmare a constrângerii fizice sau morale a creditorului întreţinerii;","lvl":2},{"k":"lit","n":"c","id":"a1.lc","t":"stabilire a faptului de falsificare a hotărârii instanţei judecătoreşti, a contractului privind plata pensiei de întreţinere sau a titlului executoriu în baza cărora a fost plătită pensia.","lvl":2},{"k":"al","n":"2","id":"a2","t":"În cazul în care contravenţiile menţionate la alin.(1) au fost comise de către reprezentantul copilului minor sau al persoanei supuse unei măsuri de ocrotire judiciare care primea pensia de întreţinere, aceasta nu se reîncasează, iar sumele plătite anterior vor fi încasate, la cererea debitorului întreţinerii, de la reprezentantul vinovat.","lvl":1,"r":[[46,54,{"al":"1","art":"107"}]]}]},{"id":"108","num":"108","title":"Cuantumul pensiei de întreținere stabilite într-o sumă bănească fixă","node":"n20","blocks":[{"k":"al","n":"1","id":"a1","t":"Cuantumul pensiei de întreținere stabilite de instanța judecătorească într-o sumă bănească fixă constituie cel puțin 50% din valoarea mediei anuale a minimului de existență calculată pentru categoria de populație corespunzătoare pentru anul precedent de către Biroul Național de Statistică.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Cuantumul pensiei de întreținere prevăzute la alin. (1) se ajustează anual, începând cu luna aprilie, în funcție de creșterea procentuală a valorii mediei anuale a minimului de existență calculate de Biroul Național de Statistică, fără a fi necesară pronunțarea unei noi hotărâri în acest sens. În cazul în care debitorul are restanțe la plata pensiei de întreținere, plata se face conform valorii minimului de existență aplicabile la momentul efectuării acesteia.","lvl":1,"r":[[46,55,{"al":"1","art":"108"}]]},{"k":"al","n":"3","id":"a3","t":"Sarcina ajustării anuale a cuantumului pensiei de întreținere în funcție de creșterea procentuală a valorii mediei anuale a minimului de existență calculate de Biroul Național de Statistică îi revine debitorului întreținerii.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Hotărârea instanței judecătorești prin care s-a stabilit pensia de întreținere într-o sumă bănească fixă reprezintă un titlu executoriu. În cazul în care debitorul întreținerii nu efectuează plata pensiei în cuantumul stabilit, creditorul se poate adresa executorului judecătoresc în a cărui rază teritorială se află domiciliul debitorului întreținerii pentru executarea silită a hotărârii.","lvl":1}]},{"id":"109","num":"109","title":"Plata pensiei de întreţinere în cazul în care debitorul întreţinerii îşi stabileşte domiciliul în străinătate","node":"n20","blocks":[{"k":"al","n":"1","id":"a1","t":"Debitorul întreţinerii care îşi stabileşte domiciliul în străinătate este în drept să încheie cu creditorul întreţinerii un contract privind plata pensiei de întreţinere în modul prevăzut de prezentul cod.","lvl":1},{"k":"al","n":"2","id":"a2","t":"În cazul în care nu se ajunge la un acord, persoana interesată poate porni în instanţa judecătorească o acţiune privind stabilirea cuantumului pensiei de întreţinere într-o sumă fixă şi achitarea acesteia printr-o plată unică sau privind transmiterea anumitelor bunuri în contul pensiei sau privind determinarea unui alt mod de plată a acesteia.","lvl":1}]},{"id":"110","num":"110","title":"Modificarea cuantumului pensiei de întreţinere stabilite de instanţa judecătorească sau scutirea de plata acesteia","node":"n20","blocks":[{"k":"p","id":"x1","t":"În cazul în care starea materială sau familială a uneia dintre părţi s-a schimbat, instanţa judecătorească, luând în considerare şi alte circumstanţe importante ale părţilor, este în drept, la cererea oricăreia dintre ele, să modifice cuantumul pensiei de întreţinere sau să-l scutească pe debitorul întreţinerii de plata acesteia.","lvl":1}]},{"id":"111","num":"111","title":"Stingerea obligaţiei de întreţinere","node":"n20","blocks":[{"k":"al","n":"1","id":"a1","t":"Obligaţia de întreţinere, apărută în baza contractului privind plata pensiei de întreţinere, încetează în urma decesului uneia dintre părţi, a expirării duratei contractului sau conform clauzelor acestuia.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Plata pensiei de întreţinere, în baza hotărârii instanţei judecătoreşti, încetează în cazurile:","lvl":1},{"k":"lit","n":"a","id":"a2.la","t":"atingerii de către copil a vârstei de 18 ani sau obţinerii de către acesta a capacităţii depline de exerciţiu sub vârsta de 18 ani;","lvl":2},{"k":"lit","n":"b","id":"a2.lb","t":"adopţiei copilului care primeşte pensia de întreţinere;","lvl":2},{"k":"lit","n":"c","id":"a2.lc","t":"căsătoriei descendentului inapt de muncă;","lvl":2},{"k":"lit","n":"d","id":"a2.ld","t":"restabilirii capacităţii de muncă a persoanei care primeşte pensia de întreţinere;","lvl":2},{"k":"lit","n":"e","id":"a2.le","t":"recăsătoririi fostului soţ inapt de muncă care primeşte pensia de întreţinere;","lvl":2},{"k":"lit","n":"f","id":"a2.lf","t":"decesului creditorului întreţinerii sau al debitorului întreţinerii;","lvl":2},{"k":"lit","n":"g","id":"a2.lg","t":"anulării hotărârii judecătoreşti privind încasarea pensiei.","lvl":2}]},{"id":"142","num":"142","title":"Instituirea tutelei şi curatelei","node":"n22","blocks":[{"k":"al","n":"1","id":"a1","t":"Tutela şi curatela se instituie asupra copiilor cărora li s-a stabilit statut de copil rămas temporar fără ocrotire părintească sau de copil rămas fără ocrotire părintească în scopul creșterii, educației şi instruirii acestora, precum şi al apărării drepturilor şi intereselor lor legitime.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Tutela se instituie asupra copiilor care nu au atins vârsta de 14 ani. La atingerea vârstei de 14 ani, tutela se transformă în curatelă, fără emiterea unei dispoziții suplimentare de către autoritatea tutelară.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Curatela se instituie asupra copiilor în vârstă de la 14 la 18 ani.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Tutela și curatela asupra copiilor rămaşi temporar fără ocrotire părintească, copiilor rămaşi fără ocrotire părintească se instituie prin dispoziţia autorităţii tutelare teritoriale, în conformitate cu prevederile Legii nr. 140/2013 privind protecţia specială a copiilor aflaţi în situaţii de risc şi a copiilor separaţi de părinţi.","lvl":1,"r":[[214,232,{"a":"lege:140/2013","whole":true}]]},{"k":"al","n":"5","id":"a5","t":"- abrogat.","lvl":1}]},{"id":"143","num":"143","title":"Persoanele care pot fi numite tutori (curatori)","node":"n22","blocks":[{"k":"al","n":"1","id":"a1","t":"Pot fi numiţi tutori (curatori) o singură persoană fizică sau soțul şi soţia împreună dacă nu se află în vreunul din cazurile de incompatibilitate prevăzute la alin. (4) şi au consimţit expres.","lvl":1,"r":[[160,169,{"al":"4","art":"143"}]]},{"k":"al","n":"2","id":"a2","t":"La numirea tutorelui (curatorului) se iau în considerare calitățile morale şi alte calități personale, posibilitățile candidatului de a-şi îndeplini obligaţiile de tutore (curator), relaţiile lui şi ale membrilor familiei lui cu copilul.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Numirea tutorelui la copilul care a atins vârsta de 10 ani se face numai cu acordul copilului.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Nu poate fi numită tutore (curator) persoana:","lvl":1},{"k":"lit","n":"a","id":"a4.la","t":"minoră;","lvl":2},{"k":"lit","n":"b","id":"a4.lb","t":"în privinţa căreia este instituită o măsura de ocrotire judiciară;","lvl":2},{"k":"lit","n":"c","id":"a4.lc","t":"decăzută din drepturile părinteşti;","lvl":2},{"k":"lit","n":"d","id":"a4.ld","t":"declarată incapabilă de a fi tutore (curator) din cauza stării de sănătate;","lvl":2},{"k":"lit","n":"e","id":"a4.le","t":"care a fost adoptator, dar adopţia a fost anulată din cauza exercitării necorespunzătoare a obligaţiilor de adoptator;","lvl":2},{"k":"lit","n":"f","id":"a4.lf","t":"căreia i s-a restrâns exerciţiul unor drepturi politice sau civile, fie în temeiul legii, fie prin hotărâre judecătorească, precum şi persoana cu rele purtări;","lvl":2},{"k":"lit","n":"g","id":"a4.lg","t":"ale cărei interese vin în conflict cu interesele persoanei puse sub tutelă (curatelă);","lvl":2},{"k":"lit","n":"h","id":"a4.lh","t":"înlăturată, prin act autentic sau prin testament, de către părintele care exercita singur, pînă la momentul morții, ocrotirea părintească;","lvl":2},{"k":"lit","n":"i","id":"a4.li","t":"care, exercitând o tutelă (curatelă), a fost îndepărtată de la ea;","lvl":2},{"k":"lit","n":"j","id":"a4.lj","t":"care suferă de alcoolism cronic sau de narcomanie;","lvl":2},{"k":"lit","n":"k","id":"a4.lk","t":"care se află în relaţii de muncă cu instituţia în care este internat copilul asupra căruia se instituie tutela (curatela);","lvl":2},{"k":"lit","n":"l","id":"a4.ll","t":"care nu are domiciliul pe teritoriul Republicii Moldova.","lvl":2}]},{"id":"144","num":"144","title":"abrogat.","node":"n22","blocks":[],"abrogat":true},{"id":"145","num":"145","title":"Drepturile copiilor aflaţi sub tutelă (curatelă)","node":"n22","blocks":[{"k":"p","id":"x1","t":"Copiii aflaţi sub tutelă (curatelă) au dreptul:","lvl":1},{"k":"lit","n":"a","id":"la","t":"de a locui împreună cu tutorele (curatorul) lor;","lvl":1},{"k":"lit","n":"b","id":"lb","t":"la condiţii normale de întreţinere, educaţie şi instruire;","lvl":1},{"k":"lit","n":"c","id":"lc","t":"la dezvoltare multilaterală şi la respectarea demnităţii umane;","lvl":1},{"k":"lit","n":"d","id":"ld","t":"la pensia de întreţinere şi la alte plăţi sociale;","lvl":1},{"k":"lit","n":"e","id":"le","t":"la spaţiul locativ ocupat anterior de către părinţii lor sau la asigurarea cu spaţiu locativ, în modul stabilit;","lvl":1},{"k":"lit","n":"f","id":"lf","t":"la apărarea drepturilor lor în modul stabilit;","lvl":1},{"k":"lit","n":"g","id":"lg","t":"la comunicare cu părinţii şi rudele;","lvl":1},{"k":"lit","n":"h","id":"lh","t":"la exprimarea propriei opinii în procesul soluţionării problemelor care le ating drepturile şi interesele legitime.","lvl":1}]},{"id":"146","num":"146","title":"Drepturile şi obligaţiile tutorelui (curatorului)","node":"n22","blocks":[{"k":"al","n":"1","id":"a1","t":"Tutorele (curatorul) are dreptul şi este obligat să se ocupe de educaţia copilului aflat sub tutela (curatela) sa, să aibă grijă de sănătatea şi dezvoltarea fizică, psihică, spirituală şi morală a copilului.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Tutorele (curatorul) determină de sine stătător procedeele şi mijloacele de educaţie a copilului aflat sub tutelă (curatelă), luând în considerare eventualele recomandări ale autorităţii tutelare teritoriale şi respectând prevederile art.62.","lvl":1,"r":[[234,240,{"art":"62"}]]},{"k":"al","n":"3","id":"a3","t":"Tutorele (curatorul), ținând cont de opinia copilului, poate alege instituţia de învățământ şi forma de studii pe care le va urma copilul, fiind obligat să asigure frecventarea de către copil a şcolii pînă la sfârșitul anului de învățământ în care acesta atinge vârsta de 16 ani.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Tutorele (curatorul) este în drept să ceară de la orice persoană, inclusiv rudele apropiate, înapoierea copilului pe care acestea îl reţin fără temei legal sau fără o hotărâre corespunzătoare a instanţei judecătoreşti.","lvl":1},{"k":"al","n":"5","id":"a5","t":"Tutorele (curatorul) nu este în drept să împiedice contactele copilului cu rudele lui, cu excepţia cazurilor în care contactele respective contravin intereselor acestuia.","lvl":1},{"k":"al","n":"6","id":"a6","t":"Drepturile şi obligaţiile tutorelui (curatorului) privind reprezentarea intereselor copilului aflat sub tutela (curatela) sa sînt stabilite de legislaţia civilă.","lvl":1},{"k":"al","n":"7","id":"a7","t":"Tutorele (curatorul) este obligat să locuiască împreună cu copilul aflat sub tutela (curatela) sa. Curatorul şi copilul aflat sub curatelă care a atins vârsta de 14 ani pot locui separat doar cu acordul autorităţii tutelare teritoriale, care a dispus plasamentul planificat.","lvl":1},{"k":"al","n":"8","id":"a8","t":"Tutorele (curatorul) este obligat să comunice autorităţii tutelare în a cărei evidenţă se află copilul informaţiile privind starea sănătăţii, îngrijirea şi educaţia copilului, precum şi schimbarea domiciliului.","lvl":1}]},{"id":"147","num":"147","title":"Exercitarea drepturilor şi îndeplinirea obligaţiilor de tutore (curator)","node":"n22","blocks":[{"k":"al","n":"1","id":"a1","t":"Drepturile şi obligaţiile de tutore (curator) sînt exercitate exclusiv în interesul minorului aflat sub tutelă (curatelă).","lvl":1},{"k":"al","n":"2","id":"a2","t":"Obligaţiile de tutore (curator) sînt exercitate gratuit, cu excepţiile prevăzute de lege.","lvl":1}]},{"id":"154","num":"154","title":"Aplicarea normelor dreptului familiei faţă de cetăţenii străini şi apatrizi","node":"n23","blocks":[{"k":"p","id":"x1","t":"Cetăţenii străini şi apatrizii cu domiciliul pe teritoriul Republicii Moldova, în relaţiile familiale, au aceleaşi drepturi şi obligaţii ca şi cetăţenii Republicii Moldova.","lvl":1}]},{"id":"155","num":"155","title":"Înregistrarea căsătoriei pe teritoriul Republicii Moldova","node":"n23","blocks":[{"k":"al","n":"1","id":"a1","t":"Forma şi modul de înregistrare a căsătoriei pe teritoriul Republicii Moldova de către cetăţenii străini şi apatrizi sînt determinate de legislaţia Republicii Moldova.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Cetăţenii străini, cu domiciliul în afara teritoriului Republicii Moldova, înregistrează căsătoria pe teritoriul Republicii Moldova conform legislaţiei Republicii Moldova dacă au dreptul la înregistrarea căsătoriei în conformitate cu legislaţia statului ai cărui cetăţeni sînt.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Condiţiile de înregistrare a căsătoriei de către apatrizi pe teritoriul Republicii Moldova sînt determinate de legislaţia Republicii Moldova, ţinându-se cont de legislaţia statului în care aceştia îşi au domiciliul.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Căsătoriile înregistrate la misiunile diplomatice şi oficiile consulare străine sînt recunoscute pe teritoriul Republicii Moldova în baza principiului reciprocităţii.","lvl":1}]},{"id":"156","num":"156","title":"Înregistrarea căsătoriei în afara Republicii Moldova","node":"n23","blocks":[{"k":"al","n":"1","id":"a1","t":"Cetăţenii Republicii Moldova se pot căsători în afara Republicii Moldova la misiunile diplomatice sau oficiile consulare ale Republicii Moldova.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Căsătoriile dintre cetăţenii Republicii Moldova şi căsătoriile dintre cetăţenii Republicii Moldova şi cetăţenii străini sau apatrizi înregistrate în afara Republicii Moldova în conformitate cu legislaţia ţării în care a fost înregistrată căsătoria sînt recunoscute în Republica Moldova doar în cazul dacă au fost respectate condiţiile art. 11, 14 și 15 din prezentul cod.","lvl":1,"r":[[335,342,{"art":"11"}],[344,346,{"art":"14"}],[350,352,{"art":"15"}]]}]},{"id":"157","num":"157","title":"Relaţiile personale nepatrimoniale şi patrimoniale ale soţilor","node":"n23","blocks":[{"k":"al","n":"1","id":"a1","t":"Drepturile şi obligaţiile personale nepatrimoniale şi patrimoniale ale soţilor se determină de legislaţia statului în care îşi au domiciliul comun, iar în lipsa domiciliului comun – a legislaţiei statului unde aceştia au avut ultimul domiciliu comun.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Dacă soţii nu au şi nici nu au avut anterior un domiciliu comun, drepturile şi obligaţiile lor personale nepatrimoniale şi patrimoniale se determină pe teritoriul Republicii Moldova în baza legislaţiei Republicii Moldova.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Contractul matrimonial şi contractul privind plata pensiei de întreţinere, în baza unui acord dintre soţi, pot fi supuse legislaţiei statului unde îşi are domiciliul unul dintre soţi. În lipsa unui atare acord, contractelor în cauză li se aplică prevederile alin.(1) şi (2).","lvl":1,"r":[[258,266,{"al":"1","art":"157"}],[270,273,{"al":"2","art":"157"}]]}]},{"id":"158","num":"158","title":"Desfacerea căsătoriei","node":"n23","blocks":[{"k":"al","n":"1","id":"a1","t":"Desfacerea căsătoriei cu elemente de extraneitate pe teritoriul Republicii Moldova are loc conform legislaţiei Republicii Moldova.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Cetăţenii Republicii Moldova care locuiesc în afara ţării au dreptul la desfacerea căsătoriei în instanţele judecătoreşti ale Republicii Moldova, indiferent de cetăţenia şi domiciliul celuilalt soţ.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Dacă, conform legislaţiei Republicii Moldova, căsătoria poate fi desfăcută de organul stare civilă, această problemă poate fi soluţionată de misiunile diplomatice sau oficiile consulare ale Republicii Moldova.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Este recunoscută valabilă desfacerea căsătoriei în afara Republicii Moldova dacă, la soluţionarea acestei probleme, au fost respectate cerinţele legislaţiei statului corespunzător privind competenţa organelor care au adoptat hotărârea şi privind desfacerea căsătoriei.","lvl":1}]},{"id":"159","num":"159","title":"Stabilirea şi contestarea paternităţii (maternităţii)","node":"n23","blocks":[{"k":"al","n":"1","id":"a1","t":"În Republica Moldova, în cazul părinţilor (părintelui) cetăţeni străini sau apatrizi, paternitatea (maternitatea) se stabileşte şi se contestă conform legislaţiei Republicii Moldova.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Paternitatea (maternitatea) în raport cu copilul cetăţean al Republicii Moldova se stabileşte şi se contestă în Republica Moldova conform legislaţiei proprii, indiferent de domiciliul copilului.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Dacă, conform legislaţiei Republicii Moldova, este posibilă stabilirea paternităţii (maternităţii) la oficiile de stare civilă, părinţii copilului care locuiesc în străinătate sînt în drept să se adreseze cu o declaraţie privind stabilirea paternităţii (maternităţii) la misiunile diplomatice şi oficiile consulare ale Republicii Moldova dacă cel puţin unul din părinţi este cetăţean al Republicii Moldova.","lvl":1}]},{"id":"160","num":"160","title":"Drepturile şi obligaţiile părinţilor şi copiilor","node":"n23","blocks":[{"k":"al","n":"1","id":"a1","t":"Drepturile şi obligaţiile părinţilor, inclusiv obligaţia părinţilor de a-şi întreţine copiii, sînt stabilite de legislaţia statului pe al cărui teritoriu aceştia îşi au domiciliul comun. În lipsa domiciliului comun al părinţilor şi copiilor, drepturile şi obligaţiile acestora sînt reglementate de legislaţia statului al cărui cetăţean este copilul.","lvl":1},{"k":"al","n":"2","id":"a2","t":"În cazurile de asigurare a obligaţiilor de întreţinere dintre părinţi şi copii poate fi aplicată legislaţia statului al cărui cetăţean este persoana ce pretinde întreţinere.","lvl":1}]},{"id":"161","num":"161","title":"Obligaţiile de întreţinere ale copiilor şi ale altor membri ai familiei","node":"n23","blocks":[{"k":"p","id":"x1","t":"Obligaţiile de întreţinere ale copiilor şi ale altor membri ai familiei se determină în conformitate cu legislaţia statului unde îşi are domiciliul persoana care are dreptul la întreţinere, dacă contractul privind plata pensiei de întreţinere nu prevede altfel.","lvl":1}]},{"id":"164","num":"164","title":"Aplicarea normelor dreptului familiei ale statelor străine","node":"n23","blocks":[{"k":"al","n":"1","id":"a1","t":"în cazul aplicării pe teritoriul Republicii Moldova a normelor dreptului familiei ale statelor străine conţinutul acestora se determină conform interpretării oficiale sau conform practicii din statele respective.","lvl":1},{"k":"al","n":"2","id":"a2","t":"Persoanele interesate au dreptul să prezinte documente care confirmă conţinutul normelor dreptului familiei ale statului străin pe care le invocă sau să contribuie într-un alt mod la determinarea conţinutului acestor norme.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Dacă măsurile întreprinse nu permit stabilirea conţinutului normelor dreptului familiei ale statelor străine, se aplică legislaţia Republicii Moldova.","lvl":1},{"k":"al","n":"4","id":"a4","t":"Normele dreptului familiei ale statelor străine nu sînt aplicabile pe teritoriul Republicii Moldova dacă contravin moravurilor şi ordinii publice din Republica Moldova. În acest caz, se aplică legislaţia Republicii Moldova.","lvl":1}]},{"id":"165","num":"165","title":"","node":"n24","blocks":[{"k":"p","id":"x1","t":"La data intrării în vigoare a prezentului cod, se abrogă Codul căsătoriei şi familiei, aprobat prin Legea nr.914-VII din 16 decembrie 1969, cu modificările şi completările ulterioare.","lvl":1,"r":[[100,138,{"a":"lege:914/1969","whole":true}]]}]},{"id":"166","num":"166","title":"","node":"n24","blocks":[{"k":"al","n":"1","id":"a1","t":"Normele prezentului cod se aplică relaţiilor familiale care au luat naştere după intrarea lui în vigoare.","lvl":1},{"k":"al","n":"2","id":"a2","t":"În cazul relaţiilor familiale care au luat naştere pînă la intrarea în vigoare a prezentului cod, normele acestuia se vor aplica drepturilor şi obligaţiilor care vor lua naştere după intrarea lui în vigoare.","lvl":1},{"k":"al","n":"3","id":"a3","t":"Reglementările referitoare la recunoaşterea ca valabilă a căsătoriei a cărei înregistrare de stat a fost efectuată la organele de stare civilă (art.2) nu se aplică căsătoriilor înregistrate de cetăţenii Republicii Moldova cu respectarea ritualurilor religioase pe teritoriile ocupate care intrau în componenţa fostei U.R.S.S. în perioada celui de al doilea război mondial, pînă la constituirea sau reconstituirea organelor de stare civilă pe teritoriul Republicii Moldova.","lvl":1,"r":[[144,149,{"art":"2"}]]},{"k":"al","n":"4","id":"a4","t":"Reglementările privind proprietatea în devălmăşie a soţilor şi privind proprietatea personală a fiecăruia dintre soţi, prevăzute la art.20-23, se vor aplica proprietăţii obţinute de către soţi (unul dintre soţi) după intrarea în vigoare a prezentului cod.","lvl":1,"r":[[132,141,{"art":"20","art2":"23"}]]},{"k":"al","n":"5","id":"a5","t":"Condiţiile şi modul încheierii contractelor matrimoniale şi a contractelor cu privire la plata pensiei de întreţinere, reglementate la cap.6 şi 15, se aplică contractelor respective încheiate după intrarea în vigoare a prezentului cod. Contractele matrimoniale şi contractele cu privire la plata pensiei de întreţinere încheiate pînă la intrarea în vigoare a prezentului cod se vor aplica în măsura în care nu contravin acestuia.","lvl":1},{"k":"al","n":"6","id":"a6","t":"Căsătoria desfăcută pe cale judecătorească pînă la intrarea în vigoare a prezentului cod se consideră desfăcută de la data înregistrării divorţului la organul stare civilă.","lvl":1},{"k":"al","n":"7","id":"a7","t":"Stabilirea paternităţii (maternităţii), contestarea paternităţii (maternităţii) sau orice altă acţiune privitoare la starea civilă cade sub incidenţa Codului familiei şi produce efectele prevăzute de acesta şi în cazul copiilor născuţi înainte de intrarea lui în vigoare, chiar dacă cererea se află în fază de judecată.","lvl":1,"r":[[150,166,{"a":"cod:familiei","whole":true}]]},{"k":"al","n":"8","id":"a8","t":"Cererile cu privire la orice măsuri de ocrotire, acceptate în baza legilor abrogate şi aflate în fază de judecată la intrarea în vigoare a prezentului cod, vor fi soluţionate de instanţele judecătoreşti potrivit dispoziţiilor acestui cod.","lvl":1}]},{"id":"167","num":"167","title":"","node":"n24","blocks":[{"k":"p","id":"x1","t":"Guvernul, în termen de 3 luni:","lvl":1},{"k":"dash","id":"d1","t":"va aduce actele sale normative în conformitate cu prezentul cod;","lvl":1},{"k":"dash","id":"d2","t":"va adopta acte normative care să asigure aplicarea prezentului cod.","lvl":1}]}],"annexes":[]};
